INSERT INTO public.topics (id, title, slug, usmle_step, "order", section, is_free_demo, mcq_count, case_count)
INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, difficulty, "order", type) VALUES
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 52-year-old woman presents with 3 months of symmetric pain and swelling in the metacarpophalangeal and proximal interphalangeal joints of both hands, with morning stiffness lasting more than 1 hour. She also reports fatigue and low-grade fevers. Examination shows swollen, tender MCP and PIP joints bilaterally with ulnar deviation of the fingers. Labs show ESR 68 mm/hr, CRP 4.2 mg/dL, rheumatoid factor positive, and anti-cyclic citrullinated peptide (anti-CCP) antibody strongly positive. Radiographs show periarticular osteopenia and marginal erosions at the MCP joints. Which of the following is the most likely diagnosis?', '["Rheumatoid arthritis", "Osteoarthritis", "Systemic lupus erythematosus", "Psoriatic arthritis", "Gout"]'::jsonb, 0, 'Rheumatoid arthritis is correct: symmetric polyarthritis of the small joints of the hands (MCP and PIP, sparing the DIPs), prolonged morning stiffness, positive anti-CCP (highly specific for RA), positive RF, elevated inflammatory markers, and marginal erosions with periarticular osteopenia are classic. Osteoarthritis is wrong because it causes asymmetric, non-inflammatory pain worse with use, affects DIPs and the first CMC joint, and lacks elevated ESR/CRP or anti-CCP. Lupus is wrong because it typically causes non-erosive arthritis with positive ANA and anti-dsDNA, not erosive MCP disease with anti-CCP. Psoriatic arthritis is wrong because it is usually asymmetric, involves DIPs, and is associated with skin or nail psoriasis. Gout is wrong because it causes acute monoarticular attacks, usually the first MTP joint, with monosodium urate crystals.', 'Medium', 1, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 45-year-old woman has had 6 weeks of symmetric swelling of the wrists and the second and third MCP joints of both hands, with morning stiffness lasting 2 hours. She has no rash, photosensitivity, or oral ulcers. Labs show anti-CCP antibody positive, rheumatoid factor negative, ESR 54 mm/hr, and normal uric acid. Radiographs of the hands are normal. Which of the following is the most appropriate next step in management?', '["Reassure and recheck in 6 months because radiographs are normal", "Start methotrexate and refer to rheumatology", "Start allopurinol", "Start hydroxychloroquine alone and no other therapy", "Order serum uric acid and joint aspiration"]'::jsonb, 1, 'Starting methotrexate with prompt rheumatology referral is correct: this is early seropositive RA (anti-CCP positive even with negative RF), and early disease-modifying therapy prevents irreversible joint damage, so treatment should not wait for radiographic erosions. Reassurance is wrong because untreated RA progresses to erosive, deforming disease. Allopurinol is wrong because this is not gout; uric acid is normal and the pattern is symmetric inflammatory polyarthritis. Hydroxychloroquine alone is wrong because it is insufficient as monotherapy for active, erosive-risk RA; methotrexate is the anchor disease-modifying drug. Joint aspiration and uric acid testing are wrong because the presentation and positive anti-CCP already establish inflammatory RA rather than crystal arthritis.', 'Medium', 2, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 60-year-old man with a 10-year history of rheumatoid arthritis presents with progressive dyspnea on exertion and a dry cough. He is a never-smoker. Examination shows bibasilar inspiratory crackles and no wheezing. Pulmonary function tests show a restrictive pattern with reduced DLCO. High-resolution CT of the chest shows subpleural reticular opacities and honeycombing at the lung bases. Which of the following is the most likely extra-articular manifestation of his disease?', '["Rheumatoid nodules of the lung", "Pleural effusion", "Interstitial lung disease (usual interstitial pneumonia pattern)", "Bronchiolitis obliterans", "Pulmonary hypertension from vasculitis"]'::jsonb, 2, 'Interstitial lung disease with a usual interstitial pneumonia pattern is correct: it is the most common and most serious pulmonary manifestation of RA, presenting with dyspnea, dry cough, bibasilar crackles, restrictive physiology, low DLCO, and basal subpleural honeycombing on HRCT. Rheumatoid lung nodules are wrong because they appear as discrete rounded opacities, often cavitary, not diffuse reticular honeycombing. Pleural effusion is wrong because it would cause dullness to percussion and reduced breath sounds, and imaging would show fluid rather than interstitial changes. Bronchiolitis obliterans is wrong because it is an obstructive airway disease with airflow limitation, not a restrictive pattern with honeycombing. Pulmonary hypertension is wrong because it causes a loud P2 and right heart strain, not basal crackles with interstitial fibrosis.', 'Hard', 3, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 48-year-old woman with newly diagnosed rheumatoid arthritis is started on methotrexate 15 mg weekly with folic acid. She asks about monitoring. Her baseline labs are normal, including CBC, liver function tests, and creatinine. She does not drink alcohol and is not pregnant. Which of the following monitoring strategies is most appropriate?', '["No laboratory monitoring is needed once the dose is stable", "Monthly chest radiographs", "Annual bone marrow biopsy", "CBC, liver function tests, and creatinine every 4-8 weeks initially", "Weekly serum methotrexate levels"]'::jsonb, 3, 'Monitoring CBC, liver function tests, and creatinine every 4-8 weeks initially is correct: methotrexate can cause myelosuppression, hepatotoxicity, and renal injury, so regular laboratory surveillance is standard, with intervals lengthening once stable. No monitoring is wrong because methotrexate toxicity is often silent until severe cytopenias or liver injury develop. Monthly chest radiographs are wrong because they are not part of methotrexate monitoring; a baseline chest radiograph is obtained to exclude pre-existing lung disease, not repeated monthly. Annual bone marrow biopsy is wrong because it is invasive and not indicated for routine monitoring. Weekly serum methotrexate levels are wrong because drug levels do not correlate with efficacy or toxicity in low-dose weekly RA therapy.', 'Medium', 4, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 38-year-old woman with rheumatoid arthritis has been on methotrexate 20 mg weekly for 9 months with inadequate response; she still has 8 swollen joints and an elevated CRP. She has no history of tuberculosis, hepatitis B, heart failure, or malignancy. Chest radiograph is normal and interferon-gamma release assay is negative. Which of the following is the most appropriate next step in management?', '["Stop methotrexate and start prednisone alone indefinitely", "Add allopurinol", "Switch to NSAIDs alone", "Add colchicine", "Add a TNF inhibitor such as adalimumab to methotrexate"]'::jsonb, 4, 'Adding a TNF inhibitor such as adalimumab to methotrexate is correct: for RA with inadequate response to methotrexate, adding a biologic DMARD (after negative TB screening, which is documented here) is standard escalation, and combination therapy is more effective than either drug alone. Prednisone alone indefinitely is wrong because glucocorticoids are bridge therapy only; long-term use causes osteoporosis, diabetes, and infection without preventing joint damage. Allopurinol is wrong because it treats gout, not RA. NSAIDs alone are wrong because they relieve symptoms but do not modify disease progression or prevent erosions. Colchicine is wrong because it is used for gout and pericarditis, not for RA.', 'Medium', 5, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 55-year-old man with long-standing seropositive rheumatoid arthritis presents with painless, firm subcutaneous nodules over the extensor surface of both elbows and the Achilles tendons. He also has dry eyes and dry mouth. His joints are currently well controlled on methotrexate. Which of the following is the most likely explanation for these findings?', '["Rheumatoid nodules with secondary Sjogren syndrome", "Gouty tophi", "Xanthomas from hyperlipidemia", "Erythema nodosum", "Septic arthritis with cutaneous spread"]'::jsonb, 0, 'Rheumatoid nodules with secondary Sjogren syndrome is correct: firm subcutaneous nodules over extensor surfaces and pressure points are classic rheumatoid nodules in seropositive RA, and sicca symptoms (dry eyes and dry mouth) reflect secondary Sjogren syndrome, which commonly accompanies RA. Gouty tophi are wrong because tophi are chalky deposits associated with hyperuricemia and gouty arthritis, not with seropositive RA and sicca symptoms. Xanthomas are wrong because they are lipid deposits seen in familial hypercholesterolemia, typically at tendons and eyelids, without sicca features. Erythema nodosum is wrong because it causes tender red nodules on the shins, usually in sarcoidosis or IBD, and the lesions are painful and erythematous. Septic arthritis is wrong because the nodules are painless, the patient is afebrile, and there is no acute hot joint.', 'Medium', 6, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 29-year-old man presents with 2 years of progressive low back pain that is worse in the morning and at night, improves with exercise, and does not improve with rest. He also reports stiffness lasting 2 hours each morning and occasional pain in the buttocks that alternates sides. Examination shows limited lumbar flexion (positive Schober test) and tenderness over the sacroiliac joints. He is HLA-B27 positive. Radiographs show bilateral sacroiliitis with sclerosis and blurring of the sacroiliac joints. Which of the following is the most likely diagnosis?', '["Mechanical low back pain", "Ankylosing spondylitis", "Rheumatoid arthritis", "Osteoarthritis of the spine", "Fibromyalgia"]'::jsonb, 1, 'Ankylosing spondylitis is correct: inflammatory back pain in a young man (worse with rest and at night, better with exercise, prolonged morning stiffness), alternating buttock pain from sacroiliitis, limited spinal mobility, HLA-B27 positivity, and radiographic sacroiliitis define the disease. Mechanical low back pain is wrong because it worsens with activity and improves with rest, lacks morning stiffness, and has no sacroiliitis. Rheumatoid arthritis is wrong because it rarely involves the axial skeleton and sacroiliac joints, and it targets the small joints of the hands. Osteoarthritis of the spine is wrong because it affects older patients, causes pain worse with use, and does not cause inflammatory sacroiliitis. Fibromyalgia is wrong because it causes widespread pain with tender points and fatigue but no objective inflammation, sacroiliitis, or restricted spinal motion.', 'Easy', 7, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 32-year-old man with ankylosing spondylitis has persistent inflammatory back pain and morning stiffness despite 3 months of daily naproxen and a structured exercise program. He has no history of inflammatory bowel disease, uveitis, or psoriasis. He is HLA-B27 positive and his CRP is elevated. Which of the following is the most appropriate next step in management?', '["Start methotrexate as first-line therapy", "Start allopurinol", "Start a TNF inhibitor such as etanercept", "Recommend bed rest and stop all exercise", "Start oral prednisone 60 mg daily indefinitely"]'::jsonb, 2, 'Starting a TNF inhibitor such as etanercept is correct: for axial spondyloarthritis with inadequate response to NSAIDs, TNF inhibitors are the next-line therapy and are highly effective for inflammatory back pain and sacroiliitis. Methotrexate is wrong because it is ineffective for axial disease (it helps peripheral arthritis and skin disease but not spinal inflammation). Allopurinol is wrong because it treats gout, not ankylosing spondylitis. Bed rest is wrong because inactivity worsens ankylosing spondylitis; regular exercise and physical therapy are core management. High-dose prednisone indefinitely is wrong because systemic glucocorticoids have limited efficacy in axial disease and cause major long-term toxicity.', 'Medium', 8, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 41-year-old man with ankylosing spondylitis presents to the emergency department with sudden onset of severe pain, redness, and photophobia in his left eye. Visual acuity is reduced. Slit-lamp examination shows cells and flare in the anterior chamber. There is no discharge. Which of the following is the most likely diagnosis and the most appropriate initial management?', '["Bacterial conjunctivitis; treat with topical antibiotics", "Episcleritis; reassurance only", "Acute angle-closure glaucoma; pilocarpine drops", "Acute anterior uveitis; urgent ophthalmology referral and topical corticosteroids", "Herpes simplex keratitis; topical acyclovir"]'::jsonb, 3, 'Acute anterior uveitis with urgent ophthalmology referral and topical corticosteroids is correct: HLA-B27-associated acute anterior uveitis is the most common extra-articular manifestation of ankylosing spondylitis, presenting with painful red eye, photophobia, and anterior chamber cells and flare; it requires prompt ophthalmologic treatment to prevent synechiae and vision loss. Bacterial conjunctivitis is wrong because it causes discharge and irritation without photophobia, pain, or anterior chamber inflammation. Episcleritis is wrong because it is mild, painless or mildly uncomfortable, and self-limited without anterior chamber cells. Acute angle-closure glaucoma is wrong because it causes a hazy cornea, mid-dilated pupil, and markedly elevated intraocular pressure with severe headache and nausea. Herpes simplex keratitis is wrong because it causes a dendritic corneal ulcer with vesicles, not anterior chamber inflammation.', 'Hard', 9, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 35-year-old man presents with 6 months of low back pain that is worse in the morning, improves with movement, and wakes him in the second half of the night. He has no neurologic deficits. Plain radiographs of the sacroiliac joints are normal. His CRP is elevated and he is HLA-B27 positive. Which of the following is the most appropriate next step to establish the diagnosis?', '["Lumbar spine CT scan", "Bone scan", "Serum rheumatoid factor", "Electromyography", "MRI of the sacroiliac joints"]'::jsonb, 4, 'MRI of the sacroiliac joints is correct: in suspected axial spondyloarthritis with normal radiographs, MRI can detect active sacroiliitis (bone marrow edema) years before radiographic changes appear, establishing non-radiographic axial spondyloarthritis. Lumbar CT is wrong because it shows bony anatomy and late structural damage but is insensitive for early active inflammation and involves radiation. Bone scan is wrong because it is nonspecific and has been replaced by MRI for sacroiliitis. Serum rheumatoid factor is wrong because it is not associated with spondyloarthritis and does not help diagnose axial disease. Electromyography is wrong because there is no radiculopathy or neuromuscular disease; the problem is inflammatory sacroiliitis.', 'Medium', 10, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 44-year-old man with a 12-year history of plaque psoriasis presents with 4 months of pain and swelling in the distal interphalangeal joints of several fingers, with sausage-like swelling of the second digit of his right hand. Examination shows pitting of the fingernails and silvery scaly plaques on the elbows and knees. Rheumatoid factor is negative and anti-CCP is negative. Radiographs show pencil-in-cup deformity of the DIP joints. Which of the following is the most likely diagnosis?', '["Psoriatic arthritis", "Rheumatoid arthritis", "Osteoarthritis", "Gout", "Septic arthritis"]'::jsonb, 0, 'Psoriatic arthritis is correct: DIP joint involvement, dactylitis (sausage digit), nail pitting, and psoriasis plaques with negative RF and anti-CCP are classic, and the pencil-in-cup deformity on radiographs is characteristic. Rheumatoid arthritis is wrong because it typically spares the DIP joints, is usually RF or anti-CCP positive, and is not associated with psoriasis or nail pitting. Osteoarthritis is wrong because it causes non-inflammatory Heberden nodes at the DIPs in older patients without dactylitis, psoriasis, or pencil-in-cup erosions. Gout is wrong because it causes acute monoarticular attacks with hyperuricemia and urate crystals, not chronic symmetric DIP disease with skin plaques. Septic arthritis is wrong because it is an acute hot monoarticular emergency with fever and positive cultures, not a chronic polyarticular pattern.', 'Easy', 11, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 50-year-old woman with psoriatic arthritis has severe plaque psoriasis covering 15% of her body surface area and active polyarticular joint disease with 10 swollen joints. She has failed methotrexate and topical steroids. She has no history of tuberculosis, hepatitis, or heart failure. Which of the following is the most appropriate next step in management?', '["Start allopurinol", "Start a TNF inhibitor such as adalimumab after tuberculosis screening", "Start colchicine", "Start NSAIDs alone indefinitely", "Start oral prednisone 40 mg daily indefinitely"]'::jsonb, 1, 'Starting a TNF inhibitor such as adalimumab after tuberculosis screening is correct: TNF inhibitors are effective for both the skin and joint manifestations of psoriatic arthritis, and they are indicated when methotrexate has failed, provided latent TB is excluded first. Allopurinol is wrong because it treats gout, not psoriatic arthritis. Colchicine is wrong because it is used for gout and pericarditis, not psoriatic arthritis. NSAIDs alone are wrong because they relieve pain but do not control skin disease or prevent joint damage. Long-term high-dose prednisone is wrong because it can trigger severe rebound psoriasis flares on withdrawal and causes major systemic toxicity.', 'Medium', 12, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 28-year-old man presents with 3 weeks of painful swelling of his right knee and left ankle, dysuria, and bilateral eye redness and irritation. He reports a diarrheal illness with fever 4 weeks ago after eating undercooked chicken while traveling. Examination shows a swollen, warm right knee, conjunctival injection, and a painless ulcer on the glans penis. Urethral swab is negative for gonorrhea and chlamydia. Which of the following is the most likely diagnosis?', '["Rheumatoid arthritis", "Septic arthritis", "Reactive arthritis", "Gout", "Ankylosing spondylitis"]'::jsonb, 2, 'Reactive arthritis is correct: the classic triad of asymmetric oligoarthritis of the lower extremities, conjunctivitis, and urethritis (or circinate balanitis) following a gastrointestinal infection (here likely Campylobacter from undercooked chicken) defines post-infectious reactive arthritis. Rheumatoid arthritis is wrong because it causes symmetric small-joint polyarthritis of the hands, not an asymmetric lower-extremity oligoarthritis after infection. Septic arthritis is wrong because the patient is afebrile with multiple joints involved and no positive cultures; the trigger was a preceding diarrheal illness, not hematogenous seeding. Gout is wrong because it causes acute monoarthritis, usually the first MTP joint, with hyperuricemia, not a post-infectious triad. Ankylosing spondylitis is wrong because it causes inflammatory back pain and sacroiliitis, not acute peripheral arthritis with conjunctivitis and urethritis.', 'Medium', 13, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 26-year-old man develops painful swelling of his left knee and right ankle 3 weeks after an episode of dysuria and urethral discharge that was treated as chlamydial urethritis. He also has bilateral conjunctivitis. He is HLA-B27 positive. Synovial fluid from the knee shows 12,000 white cells with 80% neutrophils, no crystals, and negative Gram stain and culture. Which of the following is the most appropriate management?', '["Immediate surgical drainage of the knee", "Allopurinol and low-purine diet", "Methotrexate as the only therapy", "NSAIDs and treatment of the triggering infection if still present, with rheumatology follow-up", "Intravenous vancomycin for 6 weeks"]'::jsonb, 3, 'NSAIDs and treatment of the triggering infection if still present, with rheumatology follow-up, is correct: reactive arthritis is a sterile post-infectious arthritis treated symptomatically with NSAIDs, plus antibiotics only if the triggering infection persists; most cases resolve in months. Immediate surgical drainage is wrong because the joint is sterile (negative Gram stain and culture, no crystals), so this is not septic arthritis. Allopurinol is wrong because this is not gout; there are no urate crystals and the trigger was infection. Methotrexate alone is wrong because it is not first-line for acute reactive arthritis; it is reserved for chronic or refractory cases. Intravenous vancomycin for 6 weeks is wrong because there is no bacterial joint infection to treat.', 'Medium', 14, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 34-year-old woman with a 6-year history of ulcerative colitis presents with 2 months of pain and swelling in both knees and ankles that flares when her bowel disease flares. She also reports 3 months of low back pain that is worse in the morning and improves with exercise. Colonoscopy shows active pancolitis. Rheumatoid factor is negative and HLA-B27 is positive. Which of the following best describes her arthritis?', '["Rheumatoid arthritis", "Septic arthritis", "Osteoarthritis", "Gout", "Type 1 peripheral enteropathic arthritis with axial involvement"]'::jsonb, 4, 'Type 1 peripheral enteropathic arthritis with axial involvement is correct: type 1 peripheral arthritis is pauciarticular, involves large lower-extremity joints, and parallels bowel disease activity, while her inflammatory back pain with HLA-B27 positivity reflects coexisting axial spondyloarthritis, both of which occur in IBD. Rheumatoid arthritis is wrong because it causes symmetric small-joint hand arthritis with positive RF or anti-CCP, not large-joint oligoarthritis tracking with colitis. Septic arthritis is wrong because multiple joints are involved, she is afebrile, and the pattern follows bowel flares. Osteoarthritis is wrong because it is non-inflammatory, worse with use, and does not track with bowel disease activity. Gout is wrong because it causes acute monoarthritis with urate crystals, not chronic oligoarthritis with inflammatory back pain.', 'Hard', 15, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 30-year-old man with Crohn disease presents with 6 weeks of asymmetric swelling of the right knee and left ankle. His bowel symptoms are currently well controlled on infliximab. He has no back pain. Examination shows two swollen joints and no skin lesions. Which of the following is the most appropriate next step in management?', '["Start NSAIDs, continue infliximab, and monitor", "Add methotrexate for the peripheral arthritis", "Stop infliximab immediately", "Start allopurinol", "Joint aspiration and culture to exclude septic arthritis"]'::jsonb, 0, 'Starting NSAIDs, continuing infliximab, and monitoring is correct: type 2 peripheral enteropathic arthritis is polyarticular and independent of bowel activity, and his bowel disease is already controlled on a TNF inhibitor that also treats the arthritis, so NSAIDs for symptom control with continued biologic therapy is appropriate. Adding methotrexate is wrong because his arthritis is already being treated by infliximab and there is no indication for additional immunosuppression. Stopping infliximab is wrong because it is controlling his Crohn disease and also treats spondyloarthritis. Allopurinol is wrong because this is not gout. Joint aspiration is wrong because there are no features of septic arthritis (no fever, no single hot joint, and a clear IBD-associated pattern), so invasive testing is unnecessary.', 'Hard', 16, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 24-year-old man presents with 1 year of low back pain that is worse at night and in the morning, improves with exercise, and is associated with 1 hour of morning stiffness. He has no psoriasis, inflammatory bowel disease, or urethritis. Examination shows tenderness over the sacroiliac joints and reduced lumbar flexion. Radiographs of the sacroiliac joints show grade 2 bilateral sacroiliitis. Which of the following best classifies his disease?', '["Peripheral spondyloarthritis", "Axial spondyloarthritis", "Rheumatoid arthritis", "Polymyalgia rheumatica", "Mechanical low back pain"]'::jsonb, 1, 'Axial spondyloarthritis is correct: inflammatory back pain with sacroiliitis on imaging in a young man defines axial disease, which predominantly involves the spine and sacroiliac joints. Peripheral spondyloarthritis is wrong because it is defined by arthritis, enthesitis, or dactylitis of the limbs without predominant axial involvement. Rheumatoid arthritis is wrong because it targets the small joints of the hands and does not cause sacroiliitis. Polymyalgia rheumatica is wrong because it affects patients over 50 with proximal shoulder and hip girdle pain and markedly elevated ESR, not sacroiliitis in a young man. Mechanical low back pain is wrong because it worsens with activity, improves with rest, and lacks inflammatory features or sacroiliitis.', 'Easy', 17, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 27-year-old woman presents with 4 months of swelling and pain in her right knee, left ankle, and the Achilles tendon insertion of her right heel. She has no back pain, no psoriasis, and no history of inflammatory bowel disease or preceding infection. HLA-B27 is positive. Radiographs of the spine and sacroiliac joints are normal. Which of the following best classifies her disease?', '["Axial spondyloarthritis", "Rheumatoid arthritis", "Peripheral spondyloarthritis", "Osteoarthritis", "Fibromyalgia"]'::jsonb, 2, 'Peripheral spondyloarthritis is correct: asymmetric oligoarthritis of the lower limbs with enthesitis (Achilles tendon insertion pain) and HLA-B27 positivity, without axial symptoms or sacroiliitis, defines peripheral spondyloarthritis. Axial spondyloarthritis is wrong because she has no inflammatory back pain or sacroiliitis. Rheumatoid arthritis is wrong because it causes symmetric small-joint polyarthritis of the hands, not asymmetric lower-limb oligoarthritis with enthesitis. Osteoarthritis is wrong because it is non-inflammatory, worse with use, and does not cause enthesitis or HLA-B27-associated arthritis. Fibromyalgia is wrong because it causes widespread pain without objective joint swelling, enthesitis, or inflammatory markers.', 'Medium', 18, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 47-year-old woman with rheumatoid arthritis for 8 years presents with progressive deformity of the hands: ulnar deviation of the fingers, swan-neck deformities, and subluxation of the MCP joints. She has difficulty gripping objects and buttoning her clothes. Her disease is currently in remission on methotrexate and adalimumab. Which of the following is the most appropriate next step in management?', '["Increase methotrexate dose", "Start high-dose prednisone", "Stop all disease-modifying therapy", "Refer to hand surgery and occupational therapy for deformity management", "Start allopurinol"]'::jsonb, 3, 'Referral to hand surgery and occupational therapy is correct: established deformities in RA are irreversible structural damage, not active inflammation, so management focuses on splinting, occupational therapy, assistive devices, and surgical correction when indicated, while continuing disease-modifying therapy to prevent further damage. Increasing methotrexate is wrong because her disease is in remission and the deformity is structural, not inflammatory. High-dose prednisone is wrong because there is no active synovitis to suppress and steroids do not reverse deformity. Stopping all disease-modifying therapy is wrong because it risks a flare and further joint damage. Allopurinol is wrong because it treats gout, not RA.', 'Medium', 19, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 62-year-old man with rheumatoid arthritis on methotrexate 20 mg weekly presents with fever, cough, and dyspnea for 5 days. Chest radiograph shows a right lower lobe infiltrate. He is started on antibiotics for community-acquired pneumonia. Which of the following is the most appropriate action regarding his methotrexate?', '["Continue methotrexate at the same dose", "Double the methotrexate dose to control inflammation", "Stop methotrexate permanently", "Switch methotrexate to daily dosing", "Hold methotrexate during the acute infection"]'::jsonb, 4, 'Holding methotrexate during the acute infection is correct: immunosuppressive therapy should be temporarily withheld during serious infection to allow the immune response to clear the infection, then resumed once the infection resolves. Continuing it is wrong because methotrexate impairs immune function and can worsen infection. Doubling the dose is wrong because it would further suppress immunity and increase toxicity. Stopping it permanently is wrong because the hold is temporary; long-term RA control still requires disease-modifying therapy. Switching to daily dosing is wrong because methotrexate is given weekly for RA; daily dosing causes severe toxicity.', 'Medium', 20, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 58-year-old woman presents with 3 months of symmetric pain and stiffness in the small joints of both hands, with morning stiffness lasting 90 minutes. She has a history of smoking and her mother had rheumatoid arthritis. Labs show anti-CCP antibody positive, rheumatoid factor positive, ESR 72 mm/hr, and normal anti-dsDNA. Radiographs show soft tissue swelling and juxta-articular osteopenia without erosions. Which of the following is the strongest predictor of erosive, progressive disease in this patient?', '["Positive anti-CCP antibody", "Female sex", "Normal radiographs", "Absence of extra-articular features", "Morning stiffness of 90 minutes"]'::jsonb, 0, 'Positive anti-CCP antibody is correct: anti-CCP positivity is the strongest serologic predictor of erosive, progressive RA and is associated with more aggressive joint destruction, which is why early aggressive treatment is indicated. Female sex is wrong because although RA is more common in women, sex alone does not predict erosive progression as strongly as anti-CCP. Normal radiographs are wrong because they reflect early disease, not a benign course; erosions develop later without treatment. Absence of extra-articular features is wrong because it does not predict a mild course; many patients with erosive disease have no extra-articular manifestations. Morning stiffness duration is wrong because it reflects current inflammation, not long-term erosive risk.', 'Hard', 21, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 36-year-old man with ankylosing spondylitis is on etanercept with good control of his back pain. He presents with 2 weeks of worsening dyspnea and a productive cough. Chest radiograph shows bilateral infiltrates and he is diagnosed with pneumonia. His temperature is 38.8 C and his oxygen saturation is 91% on room air. Which of the following is the most appropriate action regarding his etanercept?', '["Continue etanercept to prevent a disease flare", "Hold etanercept during the acute infection", "Increase the etanercept dose", "Switch etanercept to methotrexate immediately", "Stop etanercept permanently"]'::jsonb, 1, 'Holding etanercept during the acute infection is correct: TNF inhibitors impair host defense against infection, so they should be temporarily withheld during serious infections such as pneumonia and resumed after the infection resolves. Continuing it is wrong because ongoing TNF blockade worsens infection risk and severity. Increasing the dose is wrong because it would further suppress immunity during an active infection. Switching to methotrexate immediately is wrong because methotrexate is also immunosuppressive and is not a substitute during acute infection. Stopping it permanently is wrong because the hold is temporary and etanercept is controlling his ankylosing spondylitis.', 'Medium', 22, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 31-year-old man presents with 8 months of inflammatory low back pain and morning stiffness. He is HLA-B27 positive. Radiographs show bilateral grade 3 sacroiliitis with partial ankylosis. He also has a history of recurrent episodes of red, painful eyes. He is started on a TNF inhibitor. Which of the following should be screened for before starting therapy?', '["Serum uric acid level", "Fasting lipid panel only", "Latent tuberculosis with interferon-gamma release assay and chest radiograph", "Thyroid function tests only", "Serum calcium level"]'::jsonb, 2, 'Screening for latent tuberculosis with an interferon-gamma release assay and chest radiograph is correct: TNF inhibitors can reactivate latent tuberculosis, so screening is mandatory before initiation, along with hepatitis B screening. Serum uric acid is wrong because it is relevant to gout, not to TNF inhibitor safety. A fasting lipid panel alone is wrong because although lipids are checked as part of general care, they are not the critical pre-biologic screen. Thyroid function tests alone are wrong because they do not address the infection risk of TNF blockade. Serum calcium is wrong because it has no role in pre-biologic screening.', 'Easy', 23, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 46-year-old woman with psoriasis of the scalp and elbows presents with 6 months of pain in the distal interphalangeal joints and swelling of the entire third toe of her left foot. She also has pitting and oil-drop discoloration of several fingernails. Rheumatoid factor is negative. Which of the following radiographic findings is most characteristic of her condition?', '["Marginal erosions with periarticular osteopenia at the MCP joints", "Subchondral sclerosis of the first MTP joint", "Chondrocalcinosis of the knees", "Pencil-in-cup deformity with DIP involvement and new bone formation", "Bamboo spine"]'::jsonb, 3, 'Pencil-in-cup deformity with DIP involvement and new bone formation is correct: psoriatic arthritis characteristically causes DIP erosions with fluffy periostitis and new bone formation, producing the pencil-in-cup appearance. Marginal erosions with periarticular osteopenia at the MCP joints are wrong because that pattern is classic for rheumatoid arthritis, which spares the DIPs. Subchondral sclerosis of the first MTP joint is wrong because it suggests osteoarthritis or gout, not psoriatic arthritis. Chondrocalcinosis is wrong because it is seen in calcium pyrophosphate deposition disease. Bamboo spine is wrong because it is the radiographic hallmark of ankylosing spondylitis, not psoriatic arthritis.', 'Medium', 24, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 39-year-old man with psoriatic arthritis has dactylitis of two toes and enthesitis at the Achilles tendon insertion. His skin psoriasis is mild, covering 2% of body surface area. He has failed NSAIDs and sulfasalazine. He has no history of tuberculosis or hepatitis. Which of the following is the most appropriate next step in management?', '["Start allopurinol", "Start colchicine", "Start hydroxychloroquine", "Reassure and continue NSAIDs alone", "Start a TNF inhibitor such as etanercept"]'::jsonb, 4, 'Starting a TNF inhibitor such as etanercept is correct: TNF inhibitors are effective for dactylitis and enthesitis in psoriatic arthritis, which are often resistant to conventional DMARDs such as sulfasalazine, and are indicated after NSAID and DMARD failure. Allopurinol is wrong because it treats gout, not psoriatic arthritis. Colchicine is wrong because it is used for gout and pericarditis, not psoriatic arthritis. Hydroxychloroquine is wrong because it is ineffective for psoriatic arthritis and can worsen skin psoriasis. Reassurance with NSAIDs alone is wrong because his disease is active with dactylitis and enthesitis despite NSAIDs, and ongoing inflammation causes joint damage.', 'Hard', 25, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 33-year-old man presents with 2 weeks of asymmetric swelling of his right knee and left ankle, red eyes, and dysuria. He reports unprotected sexual intercourse with a new partner 4 weeks ago. Nucleic acid amplification testing is positive for Chlamydia trachomatis. He is HLA-B27 positive. Which of the following organisms is the most common trigger of this syndrome?', '["Chlamydia trachomatis", "Staphylococcus aureus", "Neisseria gonorrhoeae", "Streptococcus pyogenes", "Mycobacterium tuberculosis"]'::jsonb, 0, 'Chlamydia trachomatis is correct: it is the most common sexually transmitted trigger of reactive arthritis, classically causing the triad of urethritis, conjunctivitis, and asymmetric lower-extremity oligoarthritis in HLA-B27-positive patients. Staphylococcus aureus is wrong because it causes septic arthritis, not sterile post-infectious reactive arthritis. Neisseria gonorrhoeae is wrong because it causes disseminated gonococcal infection with tenosynovitis and pustular skin lesions, a different syndrome from reactive arthritis. Streptococcus pyogenes is wrong because it causes post-streptococcal reactive arthritis and rheumatic fever, not the classic chlamydia-associated triad. Mycobacterium tuberculosis is wrong because it causes chronic granulomatous arthritis, not acute post-infectious reactive arthritis.', 'Easy', 26, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 29-year-old man with reactive arthritis following Campylobacter enteritis has persistent knee arthritis 6 months after the initial episode, despite NSAIDs and physical therapy. He has no back pain. His CRP remains elevated. Which of the following is the most appropriate next step in management?', '["Start allopurinol", "Add sulfasalazine as a disease-modifying drug", "Start colchicine", "Joint replacement surgery", "Start high-dose prednisone indefinitely"]'::jsonb, 1, 'Adding sulfasalazine is correct: for chronic or refractory peripheral reactive arthritis that persists beyond 3-6 months despite NSAIDs, sulfasalazine is the preferred conventional DMARD for peripheral joint disease. Allopurinol is wrong because it treats gout, not reactive arthritis. Colchicine is wrong because it is used for gout and pericarditis, not chronic reactive arthritis. Joint replacement is wrong because the arthritis is inflammatory and potentially reversible with DMARD therapy, not end-stage degenerative disease. Long-term high-dose prednisone is wrong because it causes major toxicity and does not provide durable disease control in reactive arthritis.', 'Hard', 27, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 28-year-old woman with ulcerative colitis presents with 3 months of inflammatory low back pain, morning stiffness, and alternating buttock pain. She has no peripheral joint swelling. Colonoscopy shows quiescent colitis. HLA-B27 is positive and MRI of the sacroiliac joints shows bilateral bone marrow edema. Which of the following is the most appropriate management?', '["Treat the bowel disease only; the back pain will resolve with colitis control", "Start methotrexate as the sole therapy", "Start a TNF inhibitor, which treats both axial arthritis and bowel disease", "Start allopurinol", "Recommend bed rest and no exercise"]'::jsonb, 2, 'Starting a TNF inhibitor is correct: axial spondyloarthritis in IBD runs independently of bowel activity, so controlling colitis alone will not treat the sacroiliitis, and TNF inhibitors (such as infliximab or adalimumab) are effective for both axial arthritis and inflammatory bowel disease. Treating bowel disease only is wrong because axial arthritis in IBD does not parallel bowel activity, unlike type 1 peripheral arthritis. Methotrexate alone is wrong because it is ineffective for axial disease. Allopurinol is wrong because it treats gout, not spondyloarthritis. Bed rest is wrong because inactivity worsens axial spondyloarthritis; exercise is essential.', 'Hard', 28, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 42-year-old man with Crohn disease has type 1 peripheral arthritis involving the knees and ankles that flares with his bowel disease. His gastroenterologist is considering therapy for a Crohn flare. Which of the following statements about type 1 peripheral enteropathic arthritis is most accurate?', '["It is polyarticular, involves small joints of the hands, and is independent of bowel activity", "It causes erosive joint destruction similar to rheumatoid arthritis", "It is associated with positive rheumatoid factor", "It is pauciarticular, involves large lower-extremity joints, and parallels bowel disease activity", "It never responds to treatment of the bowel disease"]'::jsonb, 3, 'Type 1 peripheral enteropathic arthritis is pauciarticular, involves large lower-extremity joints, and parallels bowel disease activity is correct: type 1 affects fewer than 5 joints (usually knees and ankles), flares with bowel inflammation, and improves when the bowel disease is treated. The polyarticular small-joint description is wrong because that describes type 2 peripheral arthritis, which is independent of bowel activity. Erosive destruction like RA is wrong because enteropathic arthritis is typically non-erosive. Positive rheumatoid factor is wrong because enteropathic arthritis is seronegative. The claim that it never responds to bowel treatment is wrong because type 1 arthritis improves with control of the underlying bowel disease.', 'Medium', 29, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 26-year-old man presents with 6 months of low back pain worse in the morning and at night, improving with exercise. He has no psoriasis, bowel symptoms, or urethritis. Plain radiographs of the sacroiliac joints are normal. MRI of the sacroiliac joints shows bone marrow edema consistent with active sacroiliitis. He is HLA-B27 positive with an elevated CRP. Which of the following is the most appropriate diagnosis?', '["Mechanical low back pain", "Rheumatoid arthritis", "Osteoarthritis", "Septic sacroiliitis", "Non-radiographic axial spondyloarthritis"]'::jsonb, 4, 'Non-radiographic axial spondyloarthritis is correct: inflammatory back pain with MRI evidence of active sacroiliitis but normal plain radiographs defines the non-radiographic form of axial spondyloarthritis. Mechanical low back pain is wrong because it worsens with activity, improves with rest, and has no MRI sacroiliitis. Rheumatoid arthritis is wrong because it does not cause sacroiliitis. Osteoarthritis is wrong because it affects older patients, causes pain worse with use, and does not produce inflammatory sacroiliitis on MRI. Septic sacroiliitis is wrong because it is usually unilateral with fever, severe pain, and positive cultures, not bilateral MRI edema in a young man with chronic inflammatory back pain.', 'Medium', 30, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 24-year-old woman presents with 3 months of fatigue, low-grade fever, and joint pain in her hands and wrists. She has a facial rash over her cheeks that spares the nasolabial folds, photosensitivity, and painful oral ulcers. Laboratory studies show leukopenia, an antinuclear antibody (ANA) titer of 1:640, positive anti-double-stranded DNA (anti-dsDNA) antibodies, and low C3 and C4 levels. Which of the following is the most likely diagnosis?', '["Rheumatoid arthritis", "Sjogren syndrome", "Systemic lupus erythematosus", "Systemic sclerosis", "Dermatomyositis"]'::jsonb, 2, 'The malar rash sparing the nasolabial folds, photosensitivity, oral ulcers, inflammatory arthritis, cytopenia, and positive ANA with anti-dsDNA and hypocomplementemia are classic for systemic lupus erythematosus, and anti-dsDNA is highly specific for the disease. Rheumatoid arthritis causes symmetric small-joint arthritis with morning stiffness and positive anti-CCP or rheumatoid factor but not a malar rash or anti-dsDNA. Sjogren syndrome causes sicca symptoms with anti-SSA and anti-SSB antibodies, not a malar rash or nephritis. Systemic sclerosis causes skin thickening, Raynaud phenomenon, and anti-centromere or anti-Scl-70 antibodies. Dermatomyositis causes a heliotrope rash, Gottron papules, and proximal weakness with an elevated creatine kinase.', 'Medium', 31, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 28-year-old woman with systemic lupus erythematosus on hydroxychloroquine presents with fever, worsening joint pain, and a facial rash. Laboratory studies show rising anti-dsDNA antibody titers and falling C3 and C4 levels. Blood cultures are negative, chest radiograph is normal, and urinalysis is normal. Which of the following is the most appropriate next step in management?', '["Start high-dose corticosteroids for a lupus flare", "Start broad-spectrum antibiotics for presumed sepsis", "Stop hydroxychloroquine immediately", "Start cyclophosphamide induction therapy", "Perform plasmapheresis"]'::jsonb, 0, 'Rising anti-dsDNA titers with falling complement levels, together with a malar rash and arthritis and a negative infection workup, indicate a moderate to severe lupus flare, for which high-dose corticosteroids are first-line therapy. Broad-spectrum antibiotics are not indicated when cultures and imaging show no evidence of infection. Hydroxychloroquine should be continued during a flare because it reduces flare frequency and improves long-term survival. Cyclophosphamide is reserved for organ-threatening disease such as proliferative lupus nephritis, not for a musculoskeletal and cutaneous flare. Plasmapheresis has no role in an uncomplicated lupus flare.', 'Medium', 32, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 32-year-old woman with systemic lupus erythematosus presents with progressive fatigue and jaundice. Hemoglobin is 7.8 g/dL, reticulocyte count is elevated, lactate dehydrogenase is elevated, haptoglobin is low, and the direct Coombs test is positive. Platelet count and white blood cell count are normal. Which of the following is the most likely cause of her anemia?', '["Iron deficiency anemia", "Anemia of chronic disease", "Thrombotic thrombocytopenic purpura", "Warm autoimmune hemolytic anemia", "Aplastic anemia"]'::jsonb, 3, 'A positive direct Coombs test with laboratory evidence of hemolysis, including an elevated reticulocyte count, elevated lactate dehydrogenase, and low haptoglobin, in a patient with systemic lupus erythematosus indicates warm autoimmune hemolytic anemia, which is commonly treated with corticosteroids. Iron deficiency anemia presents with a low ferritin level and microcytosis without hemolysis or a positive Coombs test. Anemia of chronic disease has a low reticulocyte count with normal lactate dehydrogenase and haptoglobin. Thrombotic thrombocytopenic purpura causes thrombocytopenia, schistocytes on smear, neurologic symptoms, and a negative Coombs test. Aplastic anemia causes pancytopenia with a low reticulocyte count and a hypocellular bone marrow.', 'Medium', 33, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 26-year-old woman with known systemic lupus erythematosus presents with a new generalized tonic-clonic seizure and confusion. She has no fever, and her glucose and electrolytes are normal. Brain MRI shows small nonspecific white matter lesions, and cerebrospinal fluid analysis is normal with negative cultures. Which of the following is the most likely diagnosis?', '["Bacterial meningitis", "Neuropsychiatric systemic lupus erythematosus", "Multiple sclerosis", "Posterior reversible encephalopathy syndrome", "Antiphospholipid syndrome with stroke"]'::jsonb, 1, 'Seizures and confusion in a patient with systemic lupus erythematosus, after exclusion of infection and metabolic causes, are most consistent with neuropsychiatric lupus, which is a diagnosis of exclusion supported by active serologic disease. Bacterial meningitis would cause fever and cerebrospinal fluid pleocytosis with a positive Gram stain or culture. Multiple sclerosis follows a relapsing course with dissemination in space and time, oligoclonal bands, and no lupus serology. Posterior reversible encephalopathy syndrome typically occurs with severe hypertension and shows posterior vasogenic edema on MRI. Antiphospholipid syndrome causes a focal thrombotic stroke, not a generalized seizure with confusion.', 'Hard', 34, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 30-year-old woman with systemic lupus erythematosus is in remission on hydroxychloroquine. She asks about long-term management of her disease. Which of the following is the most appropriate counseling?', '["Stop hydroxychloroquine now that she is in remission", "Avoid all vaccinations", "Estrogen-containing oral contraceptives can be used without restriction", "Sun protection is unnecessary", "Continue hydroxychloroquine indefinitely with annual ophthalmologic screening"]'::jsonb, 4, 'Hydroxychloroquine reduces lupus flares, improves survival, and should be continued indefinitely in all patients with systemic lupus erythematosus unless contraindicated, with annual retinal screening because of the risk of retinopathy. Stopping hydroxychloroquine increases the risk of flares and disease-related damage. Inactivated vaccines are recommended in lupus, while live vaccines are avoided during immunosuppression. Estrogen-containing contraceptives increase thrombotic risk, particularly in patients with antiphospholipid antibodies. Ultraviolet light exposure triggers lupus flares, so strict sun protection is essential. Annual eye examinations are important because hydroxychloroquine can cause irreversible retinal toxicity, and patients should report any visual changes promptly.', 'Easy', 35, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 24-year-old woman with systemic lupus erythematosus presents with new periorbital edema, blood pressure 150/95 mm Hg, and a serum creatinine of 1.6 mg/dL, up from a baseline of 0.8 mg/dL. She has 3.5 g/day of proteinuria, dysmorphic red blood cells and red blood cell casts on urinalysis, low C3, and high anti-dsDNA titers. Which of the following is the most appropriate next step?', '["Start mycophenolate mofetil immediately without further testing", "Percutaneous kidney biopsy", "Renal ultrasound only", "Increase the hydroxychloroquine dose", "Urine protein electrophoresis"]'::jsonb, 1, 'An active urinary sediment with dysmorphic red blood cells and casts, nephrotic-range proteinuria, and a rising creatinine in a patient with lupus indicate lupus nephritis, and kidney biopsy is needed to classify the disease using the International Society of Nephrology/Renal Pathology Society classes, which guides therapy. Starting immunosuppression empirically without histology risks using the wrong regimen for the class of nephritis. Renal ultrasound assesses kidney size and obstruction but cannot classify lupus nephritis. Hydroxychloroquine alone is insufficient treatment for active nephritis. Urine protein electrophoresis evaluates for myeloma and does not diagnose lupus nephritis.', 'Medium', 36, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 27-year-old woman with systemic lupus erythematosus undergoes kidney biopsy for proteinuria and a rising creatinine. The biopsy shows diffuse proliferative lupus nephritis (class IV) with crescents and endocapillary proliferation. Which of the following is the most appropriate induction therapy?', '["Hydroxychloroquine alone", "Azathioprine alone", "Nonsteroidal anti-inflammatory drugs", "Mycophenolate mofetil plus high-dose glucocorticoids", "Rituximab alone"]'::jsonb, 3, 'Class IV diffuse proliferative lupus nephritis is the most severe and organ-threatening form of lupus nephritis and requires induction immunosuppression with mycophenolate mofetil or cyclophosphamide combined with high-dose glucocorticoids. Hydroxychloroquine alone is inadequate treatment for proliferative nephritis and is used only as background therapy. Azathioprine is used for maintenance therapy after remission, not for induction of proliferative disease. Nonsteroidal anti-inflammatory drugs worsen renal function and do not treat immune-mediated nephritis. Rituximab is not first-line induction therapy for lupus nephritis. After remission is achieved, maintenance therapy with mycophenolate or azathioprine is continued, and hydroxychloroquine is kept as background therapy in all patients.', 'Medium', 37, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 29-year-old woman with systemic lupus erythematosus presents with nephrotic syndrome, including 5 g/day of proteinuria, hypoalbuminemia, edema, and hyperlipidemia. Kidney biopsy shows membranous lupus nephritis (class V) without endocapillary proliferation or crescents. Which of the following is the most appropriate treatment?', '["Mycophenolate mofetil plus glucocorticoids", "Cyclophosphamide alone without glucocorticoids", "Anticoagulation alone", "Hemodialysis", "Hydroxychloroquine alone"]'::jsonb, 0, 'Class V membranous lupus nephritis with nephrotic-range proteinuria requires immunosuppression, and mycophenolate mofetil plus glucocorticoids is first-line therapy, with calcineurin inhibitors as an alternative option. Cyclophosphamide is a possible alternative but should not be given without glucocorticoids and is not preferred for pure class V disease. Anticoagulation alone addresses the thrombotic risk of nephrotic syndrome but does not treat the underlying immune-mediated kidney injury. Hemodialysis is indicated for end-stage renal disease, not as initial therapy for nephritis. Hydroxychloroquine alone is insufficient for nephrotic-range proteinuria.', 'Hard', 38, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 31-year-old woman with lupus nephritis is receiving maintenance therapy with mycophenolate mofetil and low-dose prednisone. Her creatinine is stable. Which of the following is the best test to monitor her response to therapy and detect relapse?', '["Serum antinuclear antibody titer", "Erythrocyte sedimentation rate alone", "Urine protein-to-creatinine ratio", "Serum creatinine alone", "Anti-histone antibodies"]'::jsonb, 2, 'The urine protein-to-creatinine ratio is the key marker for monitoring response and detecting relapse in lupus nephritis, because proteinuria reflects ongoing glomerular inflammation and injury. The antinuclear antibody titer does not correlate with disease activity and is not used to monitor treatment. The erythrocyte sedimentation rate is nonspecific and can be elevated in many conditions. Serum creatinine alone is insensitive and lags behind changes in proteinuria, often rising only after substantial kidney damage has occurred. Anti-histone antibodies are associated with drug-induced lupus, not with lupus nephritis activity.', 'Medium', 39, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 52-year-old woman presents with a 2-year history of dry, gritty eyes requiring artificial tears and a dry mouth with difficulty swallowing dry food. She has bilateral parotid gland enlargement and multiple dental caries. Laboratory studies show a positive antinuclear antibody and positive anti-SSA (Ro) antibodies, and a Schirmer test measures 3 mm of wetting in 5 minutes. Which of the following is the most likely diagnosis?', '["Systemic lupus erythematosus", "Rheumatoid arthritis", "Systemic sclerosis", "Sarcoidosis", "Primary Sjogren syndrome"]'::jsonb, 4, 'Sicca symptoms with parotid enlargement, dental caries, a positive Schirmer test, and anti-SSA antibodies are characteristic of primary Sjogren syndrome, an autoimmune exocrinopathy affecting the lacrimal and salivary glands. Systemic lupus erythematosus can also cause sicca symptoms but typically presents with a malar rash, nephritis, and anti-dsDNA antibodies. Rheumatoid arthritis causes inflammatory arthritis and can cause secondary Sjogren syndrome, but this patient has no arthritis. Systemic sclerosis causes skin thickening and Raynaud phenomenon. Sarcoidosis can cause parotid enlargement in Heerfordt syndrome but is usually accompanied by hilar adenopathy, uveitis, and an elevated angiotensin-converting enzyme level.', 'Medium', 40, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 50-year-old woman with dry eyes, dry mouth, and parotid enlargement is suspected to have Sjogren syndrome. Her anti-SSA and anti-SSB antibodies are negative. Which of the following is the most appropriate confirmatory test?', '["Minor salivary gland (lip) biopsy", "Kidney biopsy", "Muscle biopsy", "Skin biopsy", "Temporal artery biopsy"]'::jsonb, 0, 'Minor salivary gland biopsy of the lip demonstrating focal lymphocytic sialadenitis is the gold standard confirmatory test for Sjogren syndrome when serology is negative, and it is a key component of the classification criteria. Kidney biopsy is used to evaluate lupus nephritis and other glomerular diseases. Muscle biopsy is used to evaluate inflammatory myopathies such as polymyositis and dermatomyositis. Skin biopsy is used to evaluate scleroderma or cutaneous vasculitis. Temporal artery biopsy is used to diagnose giant cell arteritis. Salivary gland ultrasound and sialometry can support the diagnosis, but biopsy remains the definitive test when antibodies are negative.', 'Medium', 41, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 58-year-old woman with long-standing Sjogren syndrome presents with persistent unilateral parotid gland enlargement, low C4 levels, cryoglobulinemia, and palpable purpura on her legs. Which of the following is the most appropriate next step?', '["Reassure her and continue artificial tears", "Start high-dose corticosteroids alone", "Evaluate for non-Hodgkin lymphoma with parotid gland biopsy", "Start methotrexate", "Increase the pilocarpine dose"]'::jsonb, 2, 'Patients with Sjogren syndrome have a markedly increased risk of non-Hodgkin lymphoma, and persistent parotid enlargement, low C4, cryoglobulinemia, and purpura are predictors of lymphoma development, so tissue biopsy is needed for diagnosis. Reassurance misses a potentially life-threatening malignancy. High-dose corticosteroids alone do not diagnose or treat lymphoma. Methotrexate is not lymphoma therapy and would delay diagnosis. Pilocarpine treats sicca symptoms only and does nothing for the underlying lymphoproliferative process. Early recognition matters because mucosa-associated lymphoid tissue lymphoma arising in this setting is often indolent but requires oncology referral and staging.', 'Hard', 42, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 48-year-old woman with Sjogren syndrome has severe dry mouth and dry eyes but no systemic features such as arthritis, vasculitis, or organ involvement. Which of the following is the most appropriate initial management?', '["High-dose prednisone", "Artificial tears, saliva substitutes, and pilocarpine", "Cyclophosphamide", "Hydroxychloroquine alone", "Methotrexate"]'::jsonb, 1, 'Sicca symptoms in Sjogren syndrome are treated symptomatically with artificial tears, saliva substitutes, and muscarinic agonists such as pilocarpine or cevimeline, which stimulate residual salivary and lacrimal gland function. Systemic corticosteroids and cyclophosphamide are reserved for extraglandular or systemic disease such as vasculitis or interstitial lung disease. Hydroxychloroquine may help arthralgia but does not improve sicca symptoms. Methotrexate is not first-line therapy for sicca symptoms in Sjogren syndrome. Patients should also maintain meticulous dental hygiene with fluoride, avoid xerogenic medications where possible, and use sugar-free gum or lozenges to stimulate saliva.', 'Easy', 43, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 45-year-old woman presents with Raynaud phenomenon, skin thickening extending above her elbows and knees, sclerodactyly, and dyspnea on exertion. She has bibasilar crackles on examination, and laboratory studies show positive anti-Scl-70 (anti-topoisomerase I) antibodies. Which of the following is the most likely diagnosis?', '["Limited cutaneous systemic sclerosis", "Systemic lupus erythematosus", "Dermatomyositis", "Diffuse cutaneous systemic sclerosis", "Mixed connective tissue disease"]'::jsonb, 3, 'Skin thickening proximal to the elbows and knees with anti-Scl-70 antibodies and interstitial lung disease defines diffuse cutaneous systemic sclerosis, which carries a higher risk of interstitial lung disease and scleroderma renal crisis. Limited cutaneous systemic sclerosis has skin involvement restricted to distal extremities and the face, with CREST features and anti-centromere antibodies. Systemic lupus erythematosus presents with a malar rash, anti-dsDNA antibodies, and nephritis. Dermatomyositis causes a heliotrope rash, Gottron papules, proximal weakness, and an elevated creatine kinase. Mixed connective tissue disease has overlapping features with high-titer anti-U1 RNP antibodies.', 'Medium', 44, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 55-year-old woman has had Raynaud phenomenon for many years and now has calcinosis, sclerodactyly, esophageal dysmotility, and telangiectasias. Laboratory studies show positive anti-centromere antibodies. Which of the following is the most likely diagnosis?', '["Limited cutaneous systemic sclerosis (CREST syndrome)", "Diffuse cutaneous systemic sclerosis", "Systemic lupus erythematosus", "Sjogren syndrome", "Polymyositis"]'::jsonb, 0, 'The combination of calcinosis, Raynaud phenomenon, esophageal dysmotility, sclerodactyly, and telangiectasias, known as CREST syndrome, with anti-centromere antibodies defines limited cutaneous systemic sclerosis, which carries a high risk of pulmonary arterial hypertension. Diffuse cutaneous systemic sclerosis has proximal skin thickening and anti-Scl-70 antibodies. Systemic lupus erythematosus presents with a malar rash and anti-dsDNA antibodies. Sjogren syndrome presents with sicca symptoms and anti-SSA antibodies. Polymyositis causes proximal weakness and an elevated creatine kinase without skin thickening. Patients with limited disease need regular echocardiographic screening for pulmonary arterial hypertension, which is the major cause of mortality in this subgroup.', 'Easy', 45, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 50-year-old woman with diffuse cutaneous systemic sclerosis presents with abrupt onset of blood pressure 190/120 mm Hg, headache, and a serum creatinine that has risen from 1.0 to 2.8 mg/dL over 2 days. Laboratory studies show microangiopathic hemolytic anemia and thrombocytopenia. Which of the following is the most appropriate treatment?', '["High-dose corticosteroids", "Beta-blocker therapy", "Calcium channel blocker therapy", "Discontinue all antihypertensive medications", "Angiotensin-converting enzyme inhibitor"]'::jsonb, 4, 'This presentation is scleroderma renal crisis, a hypertensive emergency with acute kidney injury, and angiotensin-converting enzyme inhibitors are life-saving and must be started immediately, even as the creatinine continues to rise. High-dose corticosteroids can precipitate scleroderma renal crisis and should be avoided. Beta-blockers worsen Raynaud phenomenon and are not appropriate therapy for renal crisis. Calcium channel blockers help Raynaud phenomenon but are inadequate treatment for renal crisis. Discontinuing antihypertensive medications would be dangerous in a hypertensive emergency. Blood pressure control with an ACE inhibitor improves survival dramatically, and the drug should be continued even if renal function worsens initially.', 'Hard', 46, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 60-year-old woman with limited cutaneous systemic sclerosis presents with progressive dyspnea on exertion and a loud pulmonic component of the second heart sound. Pulmonary function tests show an isolated reduction in diffusing capacity for carbon monoxide (DLCO). Which of the following is the most appropriate next step?', '["High-resolution CT of the chest alone", "Transthoracic echocardiogram", "Start high-dose corticosteroids", "Spirometry alone", "Chest radiograph alone"]'::jsonb, 1, 'Pulmonary arterial hypertension is a leading cause of death in limited cutaneous systemic sclerosis, and annual screening with transthoracic echocardiography is recommended, followed by right heart catheterization to confirm the diagnosis. High-resolution CT of the chest evaluates interstitial lung disease but does not diagnose pulmonary arterial hypertension. Corticosteroids do not treat pulmonary arterial hypertension and may precipitate scleroderma renal crisis. Spirometry alone and chest radiography lack sensitivity for detecting pulmonary arterial hypertension. If echocardiography suggests elevated pulmonary pressures, right heart catheterization confirms the diagnosis and guides initiation of pulmonary vasodilator therapy.', 'Medium', 47, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 48-year-old woman with systemic sclerosis presents with heartburn, dysphagia to both solids and liquids, regurgitation, and a nocturnal cough. Which of the following is the most appropriate management?', '["High-dose corticosteroids", "Calcium channel blocker therapy", "Proton pump inhibitor with head-of-bed elevation", "Prokinetic agent alone", "Esophageal dilation"]'::jsonb, 2, 'Esophageal dysmotility in systemic sclerosis causes severe gastroesophageal reflux disease and aspiration, and a proton pump inhibitor combined with lifestyle measures such as head-of-bed elevation is first-line therapy. Corticosteroids do not improve esophageal dysmotility and increase the risk of scleroderma renal crisis. Calcium channel blockers lower lower esophageal sphincter pressure and worsen reflux. Prokinetic agents have limited efficacy in a fibrotic esophagus. Esophageal dilation is reserved for strictures, not for diffuse dysmotility. Patients should also avoid late meals, stop smoking, and receive treatment for any superimposed esophageal candidiasis, which is common in this setting.', 'Medium', 48, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 52-year-old woman presents with a heliotrope rash around her eyes, Gottron papules over her knuckles, and proximal muscle weakness with difficulty rising from a chair and lifting her arms overhead. Her creatine kinase is 4,500 U/L, and she has difficulty swallowing. Which of the following is the most likely diagnosis?', '["Polymyositis", "Inclusion body myositis", "Systemic lupus erythematosus", "Dermatomyositis", "Systemic sclerosis"]'::jsonb, 3, 'The characteristic skin findings of a heliotrope rash and Gottron papules, together with proximal weakness and a markedly elevated creatine kinase, define dermatomyositis. Polymyositis causes similar weakness but has no rash. Inclusion body myositis affects older patients with distal weakness involving the finger flexors and quadriceps and responds poorly to steroids. Systemic lupus erythematosus causes a malar rash and anti-dsDNA antibodies, not Gottron papules. Systemic sclerosis causes skin thickening and Raynaud phenomenon, not inflammatory myositis. Dysphagia and respiratory muscle weakness are concerning features that may require urgent evaluation, and all patients need age-appropriate malignancy screening at diagnosis.', 'Easy', 49, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 45-year-old man presents with 4 months of progressive proximal muscle weakness without any rash. His creatine kinase is 6,000 U/L, electromyography shows myopathic changes, and muscle biopsy shows endomysial CD8-positive T-cell infiltrates invading muscle fibers. Which of the following is the most likely diagnosis?', '["Polymyositis", "Dermatomyositis", "Inclusion body myositis", "Statin-induced myopathy", "Guillain-Barre syndrome"]'::jsonb, 0, 'Proximal weakness with a markedly elevated creatine kinase and an endomysial CD8-positive T-cell infiltrate invading muscle fibers, without a rash, is diagnostic of polymyositis. Dermatomyositis has a characteristic rash with perifascicular atrophy and perivascular CD4-positive infiltrates. Inclusion body myositis shows rimmed vacuoles on biopsy with distal weakness and poor steroid response. Statin-induced myopathy resolves after drug withdrawal and does not show an inflammatory infiltrate on biopsy. Guillain-Barre syndrome is an acute ascending paralysis with areflexia, not a chronic inflammatory myopathy.', 'Medium', 50, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 58-year-old woman is newly diagnosed with dermatomyositis after presenting with a heliotrope rash, Gottron papules, and proximal muscle weakness. Which of the following is the most important next step in her evaluation?', '["Reassure her that no further workup is needed", "Start cyclophosphamide immediately", "Muscle biopsy only", "Start high-dose steroids without further evaluation", "Age-appropriate malignancy screening"]'::jsonb, 4, 'Dermatomyositis carries a markedly increased risk of malignancy, including ovarian, lung, breast, and gastrointestinal cancers, especially in older adults, so age-appropriate cancer screening is essential at the time of diagnosis. Reassurance misses an occult malignancy. Cyclophosphamide is not first-line therapy for inflammatory myopathies. Muscle biopsy confirms the diagnosis but does not address the cancer risk. Starting steroids treats the myositis but does not replace malignancy screening. Common associated cancers include ovarian, lung, breast, and gastrointestinal malignancies, and screening should be repeated if new symptoms develop during follow-up.', 'Medium', 51, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 68-year-old man presents with slowly progressive weakness over 3 years affecting his finger flexors and quadriceps, frequent falls, and mild dysphagia. His creatine kinase is only mildly elevated at 600 U/L, and he has had a poor response to corticosteroids. Which of the following is the most likely diagnosis?', '["Polymyositis", "Inclusion body myositis", "Dermatomyositis", "Myasthenia gravis", "Amyotrophic lateral sclerosis"]'::jsonb, 1, 'An older man with slowly progressive asymmetric weakness of the finger flexors and quadriceps, mild creatine kinase elevation, and poor steroid response is classic for inclusion body myositis, which shows rimmed vacuoles on muscle biopsy. Polymyositis causes proximal weakness with a markedly elevated creatine kinase and a good steroid response. Dermatomyositis presents with a characteristic rash. Myasthenia gravis causes fatigable weakness with ocular and bulbar involvement and a normal creatine kinase. Amyotrophic lateral sclerosis has upper and lower motor neuron signs without this pattern of creatine kinase elevation.', 'Hard', 52, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 50-year-old woman with dermatomyositis presents with proximal muscle weakness, dysphagia, and a creatine kinase of 5,000 U/L. Which of the following is the most appropriate initial treatment?', '["Nonsteroidal anti-inflammatory drugs alone", "Hydroxychloroquine alone", "High-dose glucocorticoids", "Physical therapy alone", "Methotrexate alone as first-line therapy"]'::jsonb, 2, 'High-dose glucocorticoids are first-line therapy for inflammatory myopathies, and steroid-sparing agents such as methotrexate or azathioprine are added later to allow steroid tapering. Nonsteroidal anti-inflammatory drugs do not control inflammatory myositis. Hydroxychloroquine helps the cutaneous manifestations of dermatomyositis but not muscle weakness. Physical therapy is an important adjunct but is not primary treatment for active myositis. Methotrexate alone is insufficient as first-line therapy for severe disease with dysphagia and a markedly elevated creatine kinase. Dysphagia increases aspiration risk, so speech and swallow evaluation is important, and intravenous immunoglobulin is an option for refractory or rapidly progressive disease.', 'Easy', 53, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 35-year-old woman presents with Raynaud phenomenon, puffy hands, inflammatory arthritis, myositis, and esophageal dysmotility, with features of both systemic lupus erythematosus and systemic sclerosis. Laboratory studies show very high-titer anti-U1 RNP antibodies and negative anti-dsDNA antibodies. Which of the following is the most likely diagnosis?', '["Systemic lupus erythematosus", "Systemic sclerosis", "Sjogren syndrome", "Mixed connective tissue disease", "Rheumatoid arthritis"]'::jsonb, 3, 'Overlapping features of systemic lupus erythematosus, systemic sclerosis, and inflammatory myositis with high-titer anti-U1 RNP antibodies define mixed connective tissue disease. Systemic lupus erythematosus would typically have anti-dsDNA antibodies with renal or central nervous system involvement. Systemic sclerosis has skin thickening with anti-Scl-70 or anti-centromere antibodies. Sjogren syndrome presents with sicca symptoms and anti-SSA antibodies. Rheumatoid arthritis causes symmetric inflammatory arthritis with anti-CCP antibodies and erosions. Pulmonary arterial hypertension is the leading cause of death in mixed connective tissue disease, so regular screening with echocardiography is recommended.', 'Medium', 54, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A patient has overlapping features of systemic lupus erythematosus, systemic sclerosis, and polymyositis. Which of the following antibodies is most specific for mixed connective tissue disease?', '["Anti-U1 RNP", "Anti-dsDNA", "Anti-Scl-70", "Anti-centromere", "Anti-SSA"]'::jsonb, 0, 'High-titer anti-U1 RNP antibodies are the serologic hallmark of mixed connective tissue disease and are required for the diagnosis. Anti-dsDNA antibodies are highly specific for systemic lupus erythematosus. Anti-Scl-70, or anti-topoisomerase I, antibodies are associated with diffuse cutaneous systemic sclerosis. Anti-centromere antibodies are associated with limited cutaneous systemic sclerosis. Anti-SSA, or anti-Ro, antibodies are associated with Sjogren syndrome and neonatal lupus. Anti-U1 RNP antibodies target the U1 small nuclear ribonucleoprotein complex involved in messenger RNA splicing, and high titers are present in nearly all patients with mixed connective tissue disease.', 'Easy', 55, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 40-year-old woman with mixed connective tissue disease presents with progressive dyspnea on exertion and a loud pulmonic component of the second heart sound. Echocardiography suggests pulmonary hypertension. Which of the following is the most appropriate next step?', '["Start high-dose corticosteroids", "Chest radiograph alone", "Reassure her and follow up in one year", "Start diuretics alone", "Right heart catheterization"]'::jsonb, 4, 'Pulmonary arterial hypertension is the leading cause of death in mixed connective tissue disease, and right heart catheterization is the gold standard to confirm the diagnosis and guide vasodilator therapy. Corticosteroids do not treat pulmonary arterial hypertension. Chest radiography is insensitive for detecting pulmonary hypertension. Reassurance misses a potentially fatal complication. Diuretics alone are inadequate treatment for pulmonary arterial hypertension and do not address the underlying vascular disease. Early detection allows initiation of pulmonary vasodilators such as endothelin receptor antagonists or phosphodiesterase-5 inhibitors, which improve symptoms and survival.', 'Medium', 56, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 60-year-old woman taking hydralazine for hypertension develops new arthralgias, pleuritis, fever, and a positive antinuclear antibody. Anti-histone antibodies are positive, anti-dsDNA antibodies are negative, and renal function is normal. Which of the following is the most likely diagnosis?', '["Systemic lupus erythematosus", "Drug-induced lupus from hydralazine", "Rheumatoid arthritis", "Systemic sclerosis", "Polymyositis"]'::jsonb, 1, 'Hydralazine is a classic cause of drug-induced lupus, which presents with arthralgia, serositis, and fever, with anti-histone antibodies and negative anti-dsDNA antibodies, sparing the kidneys and central nervous system. Systemic lupus erythematosus typically has anti-dsDNA antibodies with renal or central nervous system involvement. Rheumatoid arthritis causes erosive arthritis with anti-CCP antibodies. Systemic sclerosis causes skin thickening and Raynaud phenomenon. Polymyositis causes proximal weakness with an elevated creatine kinase. Symptoms typically resolve within weeks to months after stopping hydralazine, and slow acetylators are at higher risk of developing drug-induced lupus.', 'Medium', 57, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 65-year-old man taking procainamide for a cardiac arrhythmia develops pleuritic chest pain, arthralgias, and fever. Laboratory studies show a positive antinuclear antibody and positive anti-histone antibodies. Which of the following is the most appropriate management?', '["Continue procainamide and add corticosteroids", "Start cyclophosphamide", "Discontinue procainamide", "Start hydroxychloroquine", "Perform plasmapheresis"]'::jsonb, 2, 'Drug-induced lupus resolves after withdrawal of the offending drug, and procainamide is the most common cause, so discontinuing procainamide is the definitive treatment. Continuing the drug perpetuates the disease even if corticosteroids are added. Cyclophosphamide is unnecessary and toxic for drug-induced lupus. Hydroxychloroquine is not needed once the offending drug is stopped. Plasmapheresis has no role in drug-induced lupus. Symptoms usually resolve within weeks after drug withdrawal, although the antinuclear antibody may remain positive for months, and rechallenge with procainamide should be avoided because the syndrome will recur promptly.', 'Easy', 58, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'Which of the following features best distinguishes drug-induced lupus from idiopathic systemic lupus erythematosus?', '["Anti-dsDNA antibodies positive with nephritis", "Low complement levels with central nervous system lupus", "Malar rash with oral ulcers", "Anti-histone antibodies positive, anti-dsDNA negative, with kidneys and central nervous system spared", "Positive anti-Smith antibodies with thrombocytopenia"]'::jsonb, 3, 'Drug-induced lupus is characterized by anti-histone antibodies, absent anti-dsDNA antibodies, and sparing of the kidneys and central nervous system, with resolution after withdrawal of the offending drug. Anti-dsDNA antibodies with nephritis, low complement with central nervous system disease, a malar rash with oral ulcers, and anti-Smith antibodies with thrombocytopenia all favor idiopathic systemic lupus erythematosus rather than drug-induced lupus, which typically causes only arthralgia, serositis, and fever. Renal and central nervous system involvement are rare in drug-induced lupus, whereas they are common and often severe in idiopathic systemic lupus erythematosus.', 'Medium', 59, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 45-year-old woman with rheumatoid arthritis on infliximab develops a malar rash, arthralgias, and a positive antinuclear antibody with positive anti-dsDNA antibodies. Which of the following is the most appropriate next step?', '["Continue infliximab and add hydroxychloroquine", "Switch to another tumor necrosis factor inhibitor", "Start cyclophosphamide", "Increase the methotrexate dose", "Discontinue infliximab"]'::jsonb, 4, 'Tumor necrosis factor inhibitors such as infliximab can induce a lupus-like syndrome, and the offending drug must be discontinued, after which symptoms usually resolve over weeks to months. Continuing infliximab or switching to another tumor necrosis factor inhibitor perpetuates the syndrome. Cyclophosphamide is unnecessary and toxic for drug-induced lupus. Increasing methotrexate does not address the underlying cause, which is the tumor necrosis factor inhibitor itself. Symptoms typically improve within weeks to months after stopping the drug, and patients should not be switched to a different tumor necrosis factor inhibitor.', 'Medium', 60, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 74-year-old woman presents with a new severe temporal headache, scalp tenderness when brushing her hair, jaw pain when chewing, and transient vision loss in her right eye. She also reports low-grade fever, weight loss, and shoulder pain. Examination shows a tender, thickened right temporal artery with a diminished pulse. ESR is 92 mm/hr and CRP is elevated. Which of the following is the most appropriate next step in management?', '["Start high-dose oral prednisone immediately and arrange temporal artery biopsy within 1-2 weeks", "Order temporal artery biopsy first and withhold steroids until the result is available", "Start low-dose prednisone 10 mg daily and recheck ESR in 2 weeks", "Obtain a CT angiogram of the head and neck before starting any therapy", "Prescribe sumatriptan for presumed migraine and arrange outpatient follow-up"]'::jsonb, 0, 'This is giant cell arteritis, a large-vessel vasculitis of patients over 50 with headache, scalp tenderness, jaw claudication, polymyalgia rheumatica symptoms, markedly elevated ESR, and risk of irreversible vision loss from arteritic anterior ischemic optic neuropathy. High-dose glucocorticoids must be started immediately when GCA is suspected, before biopsy, because treatment prevents blindness in the contralateral eye; biopsy remains diagnostic for up to 2 weeks after starting steroids. Waiting for biopsy risks permanent vision loss. Low-dose prednisone is the dose for polymyalgia rheumatica, not GCA. CT angiography is not the diagnostic test of choice. Migraine does not explain the systemic features, elevated ESR, or jaw claudication.', 'Medium', 61, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 68-year-old man presents with 3 months of bilateral shoulder and hip girdle pain and stiffness, worse in the morning and lasting more than an hour, with difficulty raising his arms to comb his hair. He has low-grade fever, fatigue, and weight loss but no headache, jaw pain, or visual symptoms. ESR is 78 mm/hr and CRP is elevated. Rheumatoid factor and anti-CCP are negative, and creatine kinase is normal. Which of the following is the most likely diagnosis?', '["Polymyalgia rheumatica", "Rheumatoid arthritis", "Polymyositis", "Fibromyalgia", "Osteoarthritis of the shoulders"]'::jsonb, 0, 'Polymyalgia rheumatica presents in patients over 50 with bilateral proximal girdle pain and stiffness, morning stiffness, systemic symptoms, and a markedly elevated ESR, with negative rheumatoid factor and normal creatine kinase. It is distinct from rheumatoid arthritis, which causes symmetric small-joint synovitis and positive anti-CCP, and from polymyositis, which causes true muscle weakness with elevated creatine kinase. Fibromyalgia causes widespread pain without elevated inflammatory markers and affects younger patients. Osteoarthritis causes mechanical pain without systemic symptoms or elevated ESR. Note that PMR and giant cell arteritis frequently coexist, so the patient must be screened for headache, jaw claudication, and visual symptoms.', 'Medium', 62, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 55-year-old man presents with 6 weeks of bloody nasal discharge, recurrent sinusitis, cough with hemoptysis, and arthralgias. Urinalysis shows red blood cell casts and proteinuria, and serum creatinine is 2.4 mg/dL. Chest radiograph shows bilateral cavitary nodules. c-ANCA is positive with anti-proteinase 3 antibodies. Which of the following is the most appropriate initial treatment?', '["High-dose glucocorticoids plus rituximab", "High-dose glucocorticoids alone", "Trimethoprim-sulfamethoxazole alone", "Plasmapheresis alone", "Methotrexate plus low-dose prednisone"]'::jsonb, 0, 'This is granulomatosis with polyangiitis, an ANCA-associated small-vessel vasculitis with c-ANCA/anti-PR3 positivity, upper airway disease, cavitary pulmonary nodules, and pauci-immune glomerulonephritis. Severe organ-threatening disease requires remission induction with high-dose glucocorticoids plus rituximab (preferred) or cyclophosphamide. Glucocorticoids alone are insufficient for induction of severe GPA. Trimethoprim-sulfamethoxazole is used for Pneumocystis prophylaxis during immunosuppression and for limited disease maintenance, not as induction therapy. Plasmapheresis is reserved for severe alveolar hemorrhage or rapidly progressive renal failure, not as sole therapy. Methotrexate is used for maintenance or limited non-organ-threatening disease, not for severe disease with renal involvement.', 'Hard', 63, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 62-year-old woman presents with rapidly progressive renal failure, hematuria with red blood cell casts, and hemoptysis with diffuse alveolar infiltrates on chest imaging. She has no sinus or upper airway disease. Serology is positive for p-ANCA with anti-myeloperoxidase antibodies, and renal biopsy shows pauci-immune necrotizing crescentic glomerulonephritis. Which of the following is the most likely diagnosis?', '["Microscopic polyangiitis", "Granulomatosis with polyangiitis", "Goodpasture syndrome", "Polyarteritis nodosa", "Systemic lupus erythematosus"]'::jsonb, 0, 'Microscopic polyangiitis is an ANCA-associated small-vessel vasculitis, typically p-ANCA/anti-MPO positive, causing pauci-immune necrotizing glomerulonephritis and pulmonary capillaritis with alveolar hemorrhage, but without the upper airway granulomatous disease of GPA. GPA is usually c-ANCA/anti-PR3 positive with sinus, nasal, and cavitary lung involvement. Goodpasture syndrome is anti-GBM disease with linear immunofluorescence on biopsy, not pauci-immune, and is ANCA negative. Polyarteritis nodosa is a medium-vessel vasculitis that spares glomeruli and does not cause alveolar hemorrhage. Lupus nephritis shows immune complex deposition with positive ANA and low complement, not pauci-immune histology.', 'Medium', 64, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 48-year-old woman with a 10-year history of severe asthma and allergic rhinitis presents with worsening dyspnea, migratory pulmonary infiltrates, mononeuritis multiplex with right foot drop, and a purpuric rash on her legs. Laboratory studies show marked peripheral eosinophilia of 3,200 cells/microL and positive p-ANCA with anti-myeloperoxidase antibodies. Which of the following is the most appropriate next step in management?', '["High-dose glucocorticoids plus cyclophosphamide or rituximab", "Inhaled corticosteroids and a long-acting beta-agonist only", "Oral prednisone 10 mg daily with no additional therapy", "Anticoagulation with heparin for presumed thromboembolism", "Oral antibiotics for presumed bacterial pneumonia"]'::jsonb, 0, 'This is eosinophilic granulomatosis with polyangiitis (formerly Churg-Strauss syndrome), characterized by asthma preceding systemic vasculitis by years, marked eosinophilia, pulmonary infiltrates, mononeuritis multiplex, and often p-ANCA/anti-MPO positivity. Organ- or life-threatening disease requires high-dose glucocorticoids plus cyclophosphamide or rituximab for remission induction. Inhaled asthma therapy alone cannot treat systemic vasculitis. Low-dose prednisone is inadequate for severe multisystem disease. Anticoagulation does not address vasculitic nerve or pulmonary injury. Antibiotics are wrong because the infiltrates are eosinophilic and vasculitic rather than infectious; eosinophilia and asthma history point away from bacterial pneumonia.', 'Hard', 65, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 45-year-old man presents with livedo reticularis, painful subcutaneous nodules on his legs, testicular pain, and new-onset hypertension. He has a history of chronic hepatitis B infection. Laboratory studies show elevated ESR and CRP, negative ANCA, and normal urinalysis without red blood cell casts. Arteriography shows multiple microaneurysms of the renal and mesenteric arteries. Which of the following is the most appropriate treatment?', '["High-dose glucocorticoids plus cyclophosphamide and antiviral therapy for hepatitis B", "High-dose glucocorticoids plus rituximab", "Colchicine and allopurinol", "Plasmapheresis alone", "Methotrexate alone"]'::jsonb, 0, 'This is polyarteritis nodosa, a medium-vessel vasculitis with livedo reticularis, nodules, testicular pain, hypertension, and microaneurysms on angiography, classically associated with hepatitis B infection. Unlike ANCA-associated vasculitis, it spares glomeruli, so the urinalysis is normal, and ANCA is negative. Treatment is high-dose glucocorticoids plus cyclophosphamide for severe disease, with antiviral therapy against hepatitis B to prevent viral replication during immunosuppression. Rituximab is used for ANCA-associated vasculitis, not PAN. Colchicine and allopurinol treat gout, not vasculitis. Plasmapheresis alone is not standard therapy for PAN. Methotrexate alone is insufficient for severe medium-vessel vasculitis with organ involvement.', 'Hard', 66, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 32-year-old man of Turkish descent presents with recurrent painful oral aphthous ulcers, genital ulcers, and episodes of anterior uveitis with blurred vision. He also reports erythema nodosum-like lesions on his legs and a positive pathergy test. Which of the following is the most likely diagnosis?', '["Systemic lupus erythematosus", "Behçet disease", "Reactive arthritis", "Inflammatory bowel disease", "Herpes simplex virus infection"]'::jsonb, 1, 'Behçet disease is a systemic vasculitis characterized by recurrent oral aphthous ulcers (required for diagnosis), genital ulcers, ocular inflammation including uveitis, and skin lesions, with a positive pathergy test and a predilection for patients from the Mediterranean and Middle East, including Turkey. Lupus causes oral ulcers but also malar rash, photosensitivity, positive ANA, and renal disease, without the pathergy phenomenon. Reactive arthritis follows infection and causes arthritis, urethritis, and conjunctivitis, not recurrent genital ulcers with uveitis. Inflammatory bowel disease can cause oral ulcers and uveitis but also diarrhea, hematochezia, and weight loss, which are absent here. Recurrent herpes simplex does not cause uveitis, erythema nodosum, or a positive pathergy test.', 'Medium', 67, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 58-year-old man with a history of hypertension and chronic kidney disease presents with sudden onset of severe pain, erythema, and swelling of his right first metatarsophalangeal joint that began overnight. The joint is exquisitely tender to touch and warm. He drinks alcohol regularly and takes hydrochlorothiazide. Serum uric acid is 9.8 mg/dL. Arthrocentesis shows needle-shaped, negatively birefringent crystals under polarized light microscopy. Which of the following is the most appropriate acute treatment?', '["Start allopurinol immediately during the acute attack", "NSAIDs or colchicine for the acute attack", "Intra-articular corticosteroid injection only if NSAIDs fail in 2 weeks", "Start febuxostat and stop the diuretic permanently", "Begin prophylactic colchicine without treating the acute inflammation"]'::jsonb, 1, 'This is an acute gout attack, confirmed by needle-shaped negatively birefringent monosodium urate crystals, classically affecting the first metatarsophalangeal joint (podagra) and precipitated by alcohol and thiazide diuretics. Acute treatment is an NSAID, colchicine, or glucocorticoids to control inflammation. Urate-lowering therapy such as allopurinol should not be started during an acute attack because it can worsen or prolong the flare; it is started later for chronic management once the attack resolves. Waiting two weeks before treating a painful acute attack is inappropriate. Stopping the diuretic is reasonable but does not treat the acute attack, and febuxostat is a chronic urate-lowering agent, not acute therapy. Prophylactic colchicine alone does not treat the acute inflammation.', 'Easy', 68, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 70-year-old man with chronic tophaceous gout and a serum uric acid of 10.2 mg/dL has had three gout flares in the past year despite dietary changes. His current flare resolved two weeks ago. He has normal renal function and no history of allopurinol hypersensitivity. Which of the following is the most appropriate long-term management?', '["Continue NSAIDs daily indefinitely for flare prevention", "Start allopurinol with low-dose colchicine prophylaxis for 3-6 months, targeting uric acid below 6 mg/dL", "Start allopurinol alone without any prophylaxis", "Start pegloticase as first-line therapy", "Avoid urate-lowering therapy because his renal function is normal"]'::jsonb, 1, 'Chronic gout with tophi and frequent flares is an indication for urate-lowering therapy. Allopurinol is first-line, started after the acute flare resolves, with low-dose colchicine prophylaxis for 3 to 6 months to prevent flares triggered by the initial fall in uric acid, targeting a serum uric acid below 6 mg/dL (below 5 mg/dL with tophi). Daily NSAIDs are not appropriate long-term prophylaxis because of gastrointestinal, renal, and cardiovascular toxicity. Starting allopurinol without prophylaxis increases the risk of a precipitated flare. Pegloticase is reserved for severe refractory tophaceous gout after failure of oral agents. Normal renal function does not remove the indication for urate-lowering therapy in a patient with tophi and recurrent flares.', 'Medium', 69, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 66-year-old woman presents with acute pain and swelling of her right knee after minor trauma. She has a history of hemochromatosis. Radiograph shows chondrocalcinosis with linear calcification of the meniscus. Arthrocentesis shows rhomboid-shaped, weakly positively birefringent crystals. Which of the following is the most likely diagnosis?', '["Gout", "Calcium pyrophosphate disease (pseudogout)", "Septic arthritis", "Rheumatoid arthritis", "Osteoarthritis"]'::jsonb, 1, 'Calcium pyrophosphate disease (pseudogout) is diagnosed by rhomboid-shaped, weakly positively birefringent crystals and chondrocalcinosis on radiographs, classically affecting the knee, and is associated with hemochromatosis, hyperparathyroidism, and hypomagnesemia. Gout shows needle-shaped negatively birefringent crystals and typically affects the first metatarsophalangeal joint. Septic arthritis presents with a hot swollen joint but with purulent synovial fluid, positive Gram stain or culture, and systemic signs of infection rather than crystals. Rheumatoid arthritis causes symmetric small-joint synovitis with positive anti-CCP, not crystal deposition. Osteoarthritis causes chronic mechanical pain without acute inflammatory effusion or crystals.', 'Medium', 70, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 78-year-old woman with known calcium pyrophosphate disease presents with an acute hot, swollen, painful right knee. She has chronic kidney disease with a creatinine of 2.1 mg/dL and a history of peptic ulcer disease. Arthrocentesis shows weakly positively birefringent rhomboid crystals, a white blood cell count of 18,000 cells/microL with 80% neutrophils, and a negative Gram stain. Which of the following is the most appropriate treatment?', '["Oral indomethacin", "Intra-articular glucocorticoid injection", "Intravenous vancomycin and ceftriaxone", "Oral colchicine 0.6 mg every hour until pain resolves", "Start allopurinol"]'::jsonb, 1, 'Acute calcium pyrophosphate arthritis is treated like acute gout with anti-inflammatory therapy, but this patient cannot safely receive NSAIDs because of chronic kidney disease and peptic ulcer disease, and systemic steroids carry risks. Intra-articular glucocorticoid injection is the preferred treatment for a single involved joint, delivering effective local anti-inflammatory therapy with minimal systemic exposure. Oral indomethacin is contraindicated by her renal disease and ulcer history. Intravenous antibiotics are not indicated because the Gram stain is negative, crystals are present, and the presentation is classic for crystal arthritis rather than septic arthritis. Hourly colchicine dosing is an outdated regimen with severe gastrointestinal toxicity. Allopurinol treats gout by lowering uric acid and has no role in calcium pyrophosphate disease.', 'Hard', 71, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 72-year-old woman presents with 2 months of new headache, scalp tenderness, and jaw claudication. She also reports pain and stiffness in her shoulders and hips. ESR is 105 mm/hr. She is started on high-dose prednisone. Which of the following is the most appropriate next diagnostic step?', '["Temporal artery biopsy only after stopping steroids for 4 weeks", "Temporal artery biopsy within 1-2 weeks of starting steroids", "MRI of the brain to evaluate for stroke", "Serum protein electrophoresis", "Echocardiogram to evaluate for endocarditis"]'::jsonb, 1, 'In suspected giant cell arteritis, high-dose glucocorticoids are started immediately to prevent vision loss, and temporal artery biopsy should be performed within 1 to 2 weeks of starting treatment because histologic changes persist during this window. Stopping steroids for 4 weeks to obtain a biopsy would expose the patient to the risk of irreversible blindness. MRI of the brain is not indicated without focal neurologic deficits and does not diagnose GCA. Serum protein electrophoresis evaluates for myeloma, which does not explain headache, jaw claudication, and a markedly elevated ESR. Echocardiography is used for suspected endocarditis, which does not fit this presentation of large-vessel vasculitis.', 'Medium', 72, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 76-year-old man with polymyalgia rheumatica has been treated with prednisone 15 mg daily for 6 weeks with complete resolution of his shoulder and hip pain and normalization of his ESR. He now reports new-onset headache, scalp tenderness, and transient vision loss in his left eye. Which of the following is the most appropriate next step?', '["Stop prednisone and start methotrexate", "Continue prednisone 15 mg daily and reassure the patient", "Increase prednisone to high-dose therapy immediately and arrange urgent ophthalmology evaluation", "Obtain a temporal artery biopsy before changing the steroid dose", "Start aspirin and arrange outpatient follow-up in 2 weeks"]'::jsonb, 2, 'Polymyalgia rheumatica and giant cell arteritis frequently coexist, and this patient has developed symptoms of GCA while on low-dose prednisone, which treats PMR but is inadequate for GCA. New headache, scalp tenderness, and visual symptoms demand immediate escalation to high-dose glucocorticoids to prevent permanent vision loss, along with urgent ophthalmologic evaluation. Continuing the low dose risks irreversible blindness. Stopping prednisone would worsen both conditions, and methotrexate is not acute therapy for GCA. Waiting for a biopsy before escalating steroids risks vision loss, since treatment must precede or coincide with biopsy. Aspirin alone does not treat arteritis and outpatient follow-up in two weeks is dangerously slow.', 'Medium', 73, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 50-year-old man presents with chronic sinusitis, nasal ulcers with crusting, saddle nose deformity, and a 3-month history of cough with hemoptysis. Urinalysis shows dysmorphic red blood cells and red blood cell casts with 2+ protein. c-ANCA is positive. Which of the following laboratory findings is most characteristic of his disease?', '["Anti-glomerular basement membrane antibodies", "Anti-myeloperoxidase antibodies", "Anti-proteinase 3 antibodies", "Anti-double-stranded DNA antibodies", "Anti-cyclic citrullinated peptide antibodies"]'::jsonb, 2, 'Granulomatosis with polyangiitis is characterized by c-ANCA directed against proteinase 3, with upper airway granulomatous disease including sinusitis, nasal ulcers, and saddle nose deformity, lower airway cavitary disease, and pauci-immune glomerulonephritis. Anti-myeloperoxidase antibodies produce p-ANCA and are more typical of microscopic polyangiitis and eosinophilic granulomatosis with polyangiitis. Anti-GBM antibodies cause Goodpasture syndrome with linear immunofluorescence, not c-ANCA positivity. Anti-dsDNA antibodies are seen in systemic lupus erythematosus. Anti-CCP antibodies are highly specific for rheumatoid arthritis, which does not cause cavitary lung nodules or glomerulonephritis.', 'Easy', 74, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 58-year-old woman with granulomatosis with polyangiitis involving the kidneys and lungs has completed remission induction with rituximab and glucocorticoids. Her creatinine has improved and her hemoptysis has resolved. Which of the following is the most appropriate maintenance therapy?', '["High-dose prednisone 60 mg daily indefinitely", "Stop all immunosuppression immediately", "Rituximab for maintenance immunosuppression", "Trimethoprim-sulfamethoxazole alone", "Plasmapheresis monthly"]'::jsonb, 2, 'After remission induction for severe ANCA-associated vasculitis, maintenance immunosuppression is required to prevent relapse, and rituximab is the preferred maintenance agent, given at scheduled intervals. Stopping all immunosuppression immediately after induction leads to a high relapse rate. Continuing high-dose prednisone indefinitely causes unacceptable glucocorticoid toxicity, including diabetes, osteoporosis, and infection. Trimethoprim-sulfamethoxazole is used for Pneumocystis prophylaxis during immunosuppression and may reduce relapse in limited upper airway disease, but it is not adequate maintenance therapy for severe systemic GPA. Monthly plasmapheresis is not a maintenance strategy and is reserved for selected acute severe presentations.', 'Medium', 75, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 60-year-old man presents with rapidly progressive glomerulonephritis, hemoptysis, and a purpuric rash. He has no sinus disease or pulmonary nodules. Renal biopsy shows pauci-immune necrotizing crescentic glomerulonephritis with minimal immunoglobulin deposition. Serology is positive for p-ANCA. Which of the following is the most likely causative antibody?', '["Anti-glomerular basement membrane antibody", "Anti-proteinase 3 antibody", "Anti-myeloperoxidase antibody", "Anti-nuclear antibody", "Anti-phospholipid antibody"]'::jsonb, 2, 'Microscopic polyangiitis is an ANCA-associated small-vessel vasculitis that typically presents with rapidly progressive pauci-immune glomerulonephritis and pulmonary hemorrhage without upper airway disease, and is most commonly associated with p-ANCA directed against myeloperoxidase. Anti-proteinase 3 antibodies produce c-ANCA and are characteristic of granulomatosis with polyangiitis, which typically involves the sinuses and lungs with cavitary nodules. Anti-GBM antibodies cause Goodpasture syndrome with linear immunofluorescence on biopsy, not pauci-immune disease. Antinuclear antibody is a screening test for lupus and other connective tissue diseases, not the pathogenic antibody in ANCA-associated vasculitis. Antiphospholipid antibodies cause thrombosis and pregnancy loss, not necrotizing glomerulonephritis.', 'Medium', 76, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 52-year-old woman with a long history of asthma presents with new-onset peripheral neuropathy with foot drop, a purpuric rash, and worsening asthma control. Laboratory studies show an absolute eosinophil count of 4,500 cells/microL and elevated IgE. Chest imaging shows fleeting pulmonary infiltrates. Which of the following additional findings would most strongly support a diagnosis of eosinophilic granulomatosis with polyangiitis rather than simple asthma with eosinophilia?', '["Positive skin prick testing to dust mites", "Elevated total IgE", "Positive p-ANCA with anti-myeloperoxidase antibodies", "Bronchial hyperresponsiveness on methacholine challenge", "Elevated fractional exhaled nitric oxide"]'::jsonb, 2, 'Eosinophilic granulomatosis with polyangiitis is a systemic vasculitis in which asthma and eosinophilia precede vasculitic manifestations such as mononeuritis multiplex, purpura, and pulmonary infiltrates. Positive p-ANCA with anti-myeloperoxidase antibodies supports the vasculitic diagnosis and is present in about 40% of patients, particularly those with renal and neurologic involvement. Elevated IgE, positive skin prick testing, bronchial hyperresponsiveness, and elevated fractional exhaled nitric oxide are all features of allergic asthma and do not distinguish systemic vasculitis from asthma alone. The combination of asthma, marked eosinophilia, and systemic vasculitic features is what defines EGPA.', 'Hard', 77, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 40-year-old man presents with fever, weight loss, livedo reticularis, and mononeuritis multiplex with a right wrist drop. He has new-onset hypertension and abdominal pain after eating. Hepatitis B surface antigen is positive. ANCA testing is negative and urinalysis is normal. Which of the following is the most likely diagnosis?', '["Granulomatosis with polyangiitis", "Microscopic polyangiitis", "Polyarteritis nodosa", "Eosinophilic granulomatosis with polyangiitis", "Takayasu arteritis"]'::jsonb, 2, 'Polyarteritis nodosa is a medium-vessel vasculitis presenting with systemic symptoms, livedo reticularis, mononeuritis multiplex, hypertension from renal artery involvement, and mesenteric ischemia, classically associated with hepatitis B infection. ANCA is negative and the urinalysis is normal because glomeruli are spared, distinguishing it from ANCA-associated vasculitis. Microscopic polyangiitis causes glomerulonephritis and alveolar hemorrhage with positive p-ANCA. Granulomatosis with polyangiitis causes upper airway disease and cavitary lung nodules with positive c-ANCA. EGPA is preceded by asthma with marked eosinophilia. Takayasu arteritis is a large-vessel vasculitis of young women causing pulselessness and claudication of the arms, not mononeuritis multiplex with livedo reticularis.', 'Medium', 78, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 28-year-old woman presents with recurrent oral ulcers, genital ulcers, and painful red eyes. Ophthalmologic examination shows bilateral anterior uveitis and retinal vasculitis. She reports episodes of arthritis in her knees and erythema nodosum on her shins. Which of the following is the most appropriate first-line treatment for her ocular disease?', '["Oral antibiotics", "Topical corticosteroid eye drops alone", "Colchicine alone", "High-dose systemic glucocorticoids with azathioprine or a TNF inhibitor", "Nonsteroidal anti-inflammatory drugs alone"]'::jsonb, 3, 'Behçet disease with posterior segment ocular involvement and retinal vasculitis threatens vision and requires aggressive systemic immunosuppression with high-dose glucocorticoids plus azathioprine or a TNF inhibitor such as infliximab to preserve sight. Topical corticosteroid drops alone are inadequate for posterior uveitis and retinal vasculitis. Colchicine is useful for mucocutaneous and joint manifestations of Behçet disease but is insufficient for sight-threatening ocular disease. Antibiotics have no role because the ocular inflammation is autoimmune, not infectious. NSAIDs alone cannot control severe ocular vasculitis and will not prevent blindness.', 'Hard', 79, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 62-year-old man with gout presents with an acute painful, erythematous, swollen left first metatarsophalangeal joint. He has chronic kidney disease with a creatinine of 1.9 mg/dL and a history of gastrointestinal bleeding from NSAID use. He is not taking allopurinol. Which of the following is the most appropriate acute treatment?', '["Start allopurinol now", "Oral indomethacin", "High-dose aspirin", "Oral prednisone", "Intravenous ceftriaxone"]'::jsonb, 3, 'Acute gout can be treated with NSAIDs, colchicine, or glucocorticoids. This patient cannot safely take NSAIDs because of chronic kidney disease and prior gastrointestinal bleeding, so systemic glucocorticoids such as oral prednisone are the appropriate choice. Indomethacin is contraindicated by his renal disease and bleeding history. High-dose aspirin is ineffective for gout and can paradoxically raise uric acid levels. Allopurinol should not be started during an acute attack because it can worsen or prolong the flare. Intravenous ceftriaxone treats bacterial infection, and this presentation with a known gout history and no signs of infection does not suggest septic arthritis.', 'Medium', 80, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 45-year-old man with a body mass index of 34 kg/m2 and a history of recurrent gout flares is seen for prevention of future attacks. He drinks beer daily and eats a diet high in red meat and shellfish. His serum uric acid is 9.5 mg/dL. Which of the following lifestyle modifications is most important for reducing his risk of future gout flares?', '["Avoid drinking water to concentrate the urine", "Increase intake of red meat and shellfish", "Drink more beer and avoid all vegetables", "Reduce alcohol intake, especially beer, and limit purine-rich foods", "Increase fructose-sweetened beverage intake"]'::jsonb, 3, 'Gout is driven by hyperuricemia, and alcohol, particularly beer, increases uric acid production and decreases its renal excretion, while purine-rich foods such as red meat and shellfish raise uric acid levels. Reducing alcohol intake and limiting purine-rich foods, along with weight loss, are the key lifestyle measures for preventing flares. Increasing red meat and shellfish would worsen hyperuricemia. Beer is a major trigger, not protective, and vegetables are not a significant source of purines. Adequate hydration helps uric acid excretion, so avoiding water is harmful. Fructose-sweetened beverages increase uric acid production and should be avoided.', 'Easy', 81, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 75-year-old man presents with acute pain and swelling of his left knee. He has a history of osteoarthritis and prior total hip replacement. Arthrocentesis shows 25,000 white blood cells/microL, no organisms on Gram stain, and rhomboid-shaped positively birefringent crystals. Which of the following is the most appropriate next step in management?', '["Start allopurinol and colchicine", "Start empiric intravenous antibiotics for presumed septic arthritis", "Perform urgent surgical washout of the knee", "Treat with NSAIDs or intra-articular glucocorticoids and observe", "Order an MRI of the knee to evaluate for meniscal tear"]'::jsonb, 3, 'Calcium pyrophosphate disease presents as acute pseudogout with rhomboid-shaped positively birefringent crystals, a moderately inflammatory synovial fluid, and a negative Gram stain, and is treated with NSAIDs, colchicine, or intra-articular glucocorticoids. Empiric intravenous antibiotics and surgical washout are indicated when septic arthritis is suspected, but the presence of crystals with a negative Gram stain and a white blood cell count below 50,000 makes infection less likely, although synovial fluid culture should still be sent. Allopurinol and colchicine as a combination is a gout regimen, and allopurinol has no role in calcium pyrophosphate disease. MRI for a meniscal tear is not indicated in an acutely hot swollen joint with crystal-proven arthritis.', 'Medium', 82, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 55-year-old woman with systemic lupus erythematosus on long-term glucocorticoids presents with chronic pain and swelling of multiple joints, including the shoulders and knees. Radiographs show calcification of the articular cartilage in the knees and wrists. She has no acute joint swelling or fever. Which of the following is the most likely underlying mechanism?', '["Basic calcium phosphate (hydroxyapatite) crystal deposition", "Monosodium urate crystal deposition", "Septic arthritis", "Calcium pyrophosphate crystal deposition", "Rheumatoid arthritis"]'::jsonb, 3, 'Calcium pyrophosphate deposition disease causes chondrocalcinosis, seen as calcification of articular cartilage on radiographs, and can present with chronic polyarticular pain as well as acute pseudogout attacks; it is associated with older age, hemochromatosis, hyperparathyroidism, and hypomagnesemia. Basic calcium phosphate (hydroxyapatite) deposition typically causes acute calcific periarthritis or Milwaukee shoulder with large non-inflammatory effusions and is associated with tissue damage and long-term steroid use, but chondrocalcinosis of the cartilage is the hallmark of calcium pyrophosphate disease. Monosodium urate deposition causes gout with needle-shaped negatively birefringent crystals and tophi, not linear cartilage calcification. Septic arthritis causes an acutely hot joint with fever, which is absent. Rheumatoid arthritis causes erosive synovitis, not cartilage calcification.', 'Hard', 83, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 68-year-old woman with long-standing diabetes mellitus and end-stage renal disease on hemodialysis presents with painful calcified nodules around her shoulders and elbows, with restricted shoulder movement. Radiographs show periarticular calcifications without joint space narrowing. Synovial fluid shows non-birefringent globular calcifications. Which of the following is the most likely diagnosis?', '["Septic arthritis", "Gout", "Calcium pyrophosphate disease", "Hydroxyapatite (basic calcium phosphate) deposition disease", "Osteoarthritis"]'::jsonb, 3, 'Hydroxyapatite (basic calcium phosphate) crystal deposition disease is associated with chronic kidney disease and hemodialysis, diabetes, and tissue injury, and causes periarticular calcifications, calcific tendinitis, and the destructive Milwaukee shoulder syndrome. The crystals are small, globular, and non-birefringent on polarized microscopy, unlike the needle-shaped negatively birefringent crystals of gout or the rhomboid positively birefringent crystals of calcium pyrophosphate disease. Gout causes tophi and acute podagra, not periarticular calcification in dialysis patients. Septic arthritis presents with a hot joint, fever, and purulent fluid. Osteoarthritis causes joint space narrowing and osteophytes, not periarticular calcific deposits.', 'Hard', 84, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 70-year-old man presents with sudden onset of pain, redness, and swelling of his right great toe. He has a history of hypertension treated with hydrochlorothiazide and drinks alcohol most evenings. Arthrocentesis reveals needle-shaped crystals that appear yellow when aligned parallel to the compensator under polarized light microscopy. Which of the following best describes these crystals?', '["Calcium oxalate crystals", "Positively birefringent calcium pyrophosphate crystals", "Non-birefringent hydroxyapatite crystals", "Cholesterol crystals", "Negatively birefringent monosodium urate crystals"]'::jsonb, 4, 'Acute gout is diagnosed by needle-shaped monosodium urate crystals that are negatively birefringent, appearing yellow when aligned parallel to the red compensator and blue when perpendicular. Calcium pyrophosphate crystals are rhomboid-shaped and weakly positively birefringent, appearing blue when parallel to the compensator. Hydroxyapatite crystals are small, globular, and non-birefringent. Cholesterol crystals are seen in chronic effusions and are not diagnostic of gout. Calcium oxalate crystals are seen in urine in ethylene glycol poisoning and primary hyperoxaluria, not in synovial fluid in gout.', 'Easy', 85, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 64-year-old man with chronic tophaceous gout is started on allopurinol. Two weeks later he develops a painful swollen knee. Which of the following best explains this event and the appropriate management?', '["The flare indicates the gout has resolved; stop all therapy", "Allopurinol caused septic arthritis; stop allopurinol and start antibiotics", "Allopurinol is ineffective and should be stopped permanently", "The flare is due to allopurinol allergy; switch to febuxostat immediately during the flare", "Allopurinol lowered uric acid and mobilized urate crystals, triggering a flare; treat the flare and continue allopurinol with colchicine prophylaxis"]'::jsonb, 4, 'Starting urate-lowering therapy such as allopurinol rapidly lowers serum uric acid, which mobilizes urate from tophi and can precipitate an acute gout flare. The correct management is to treat the acute flare with an NSAID, colchicine, or glucocorticoid, continue the allopurinol, and provide low-dose colchicine prophylaxis for 3 to 6 months after initiation. The flare is not septic arthritis; stopping allopurinol would allow uric acid to rise again and is not recommended. Allopurinol is effective, and flares early in therapy are expected rather than evidence of failure. An allopurinol hypersensitivity reaction presents with rash, eosinophilia, and systemic symptoms, not an isolated joint flare, and switching agents during an acute flare is not appropriate. The flare does not mean the gout has resolved.', 'Medium', 86, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 82-year-old woman presents with acute pain and swelling of her left wrist after a fall. Radiograph shows chondrocalcinosis of the triangular fibrocartilage complex and no fracture. She has a history of hyperparathyroidism. Arthrocentesis shows weakly positively birefringent rhomboid crystals and a negative Gram stain. Which of the following is the most appropriate initial treatment?', '["Intravenous antibiotics", "Oral prednisone 60 mg daily for 4 weeks", "Allopurinol", "Methotrexate", "NSAIDs or low-dose colchicine"]'::jsonb, 4, 'Acute calcium pyrophosphate arthritis is treated with NSAIDs, low-dose colchicine, or glucocorticoids, similar to acute gout. Hyperparathyroidism is a known association of calcium pyrophosphate disease and explains the chondrocalcinosis. High-dose prednisone for 4 weeks is excessive for a single-joint crystal arthritis and carries significant toxicity in an elderly patient. Allopurinol lowers uric acid and treats gout, not calcium pyrophosphate disease. Methotrexate is a disease-modifying drug for rheumatoid arthritis and is not used for acute crystal arthritis. Intravenous antibiotics are not indicated because the Gram stain is negative, crystals are present, and there is no evidence of infection.', 'Medium', 87, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 60-year-old man presents with bilateral shoulder and hip girdle pain and stiffness for 6 weeks, worse in the morning, with an ESR of 85 mm/hr and normal creatine kinase. He has no headache, jaw pain, or visual changes. Which of the following is the most appropriate initial treatment?', '["Hydroxychloroquine alone", "Prednisone 60 mg daily indefinitely", "Methotrexate alone", "NSAIDs alone as definitive therapy", "Prednisone 15 mg daily with a rapid clinical response expected within days"]'::jsonb, 4, 'Polymyalgia rheumatica is treated with low-dose prednisone, typically 12.5 to 25 mg daily, and patients characteristically experience a dramatic improvement within days, which also supports the diagnosis. High-dose prednisone at 60 mg daily is the treatment for giant cell arteritis, not polymyalgia rheumatica, and this patient has no features of GCA. Methotrexate alone is not first-line therapy for PMR, although it may be added as a steroid-sparing agent in patients who relapse. NSAIDs alone are generally inadequate for PMR and do not produce the rapid dramatic response seen with low-dose steroids. Hydroxychloroquine is used in lupus and rheumatoid arthritis, not in polymyalgia rheumatica.', 'Medium', 88, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 66-year-old woman presents with new temporal headache, jaw claudication, and diplopia. ESR is 110 mm/hr and CRP is markedly elevated. Temporal artery biopsy is scheduled for next week. She is started on high-dose prednisone. Which of the following complications is most important to prevent with prompt treatment?', '["Temporal artery rupture", "Aortic dissection", "Stroke from carotid artery occlusion", "Myocardial infarction", "Irreversible vision loss from arteritic anterior ischemic optic neuropathy"]'::jsonb, 4, 'The most feared complication of giant cell arteritis is irreversible vision loss from arteritic anterior ischemic optic neuropathy due to occlusion of the posterior ciliary arteries supplying the optic nerve head, which is why high-dose glucocorticoids are started immediately when GCA is suspected. Although GCA can cause large-vessel complications including aortic aneurysm and dissection, stroke, and myocardial infarction, these are less common and less immediately preventable than vision loss. Diplopia in this patient reflects cranial nerve ischemia, a warning sign of impending visual loss. Temporal artery rupture is not a recognized complication of GCA. Prompt steroids protect the contralateral eye even if one eye is already affected.', 'Easy', 89, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 45-year-old man presents with recurrent sinusitis, hemoptysis, and a rising creatinine with hematuria. Chest CT shows multiple cavitary nodules. ANCA testing is positive for c-ANCA. Renal biopsy shows pauci-immune crescentic glomerulonephritis with granulomatous inflammation. Which of the following is the most likely diagnosis?', '["Cryoglobulinemic vasculitis", "Microscopic polyangiitis", "Goodpasture syndrome", "Polyarteritis nodosa", "Granulomatosis with polyangiitis"]'::jsonb, 4, 'Granulomatosis with polyangiitis is an ANCA-associated vasculitis characterized by granulomatous inflammation of the upper and lower respiratory tract, including sinusitis and cavitary pulmonary nodules, together with pauci-immune necrotizing glomerulonephritis, and is typically associated with c-ANCA/anti-proteinase 3 antibodies. Microscopic polyangiitis lacks granulomatous inflammation and upper airway disease and is usually p-ANCA/anti-MPO positive. Goodpasture syndrome is anti-GBM disease with linear immunofluorescence, not pauci-immune or c-ANCA positive. Polyarteritis nodosa is a medium-vessel vasculitis that spares the glomeruli and does not cause cavitary lung disease. Cryoglobulinemic vasculitis is associated with hepatitis C and causes purpura, arthralgias, and membranoproliferative glomerulonephritis, not cavitary nodules.', 'Medium', 90, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 62-year-old woman with a body mass index of 34 kg/m2 presents with 2 years of bilateral knee pain that worsens with walking and stair climbing and improves with rest. She reports morning stiffness lasting 15 minutes and occasional swelling after activity. Examination shows crepitus, mild varus deformity, and bony enlargement of both knees without warmth or erythema. Radiographs show medial joint space narrowing, subchondral sclerosis, and osteophyte formation. Which of the following is the most appropriate initial management?', '["Begin daily oral tramadol for pain control", "Weight loss, quadriceps-strengthening exercise, and topical diclofenac", "Intra-articular corticosteroid injection every month", "Refer immediately for total knee arthroplasty", "Start oral prednisone 20 mg daily"]'::jsonb, 1, 'This patient has classic knee osteoarthritis: age over 50, pain worse with activity, brief morning stiffness, crepitus, and radiographic joint space narrowing with osteophytes. ACR guidelines recommend weight loss and quadriceps-strengthening exercise as first-line therapy, with topical NSAIDs providing effective analgesia and fewer systemic adverse effects than oral agents. Tramadol and other opioids are not first-line because of limited benefit and dependence risk. Systemic glucocorticoids have no role in osteoarthritis. Total knee arthroplasty is reserved for severe, refractory disease after conservative measures fail. Monthly intra-articular corticosteroid injections are not recommended as initial therapy and offer only short-term relief.', 'Medium', 91, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 71-year-old man presents with 3 years of progressive right hip pain localized to the groin that now wakes him at night and causes a limp. He has tried acetaminophen, naproxen, physical therapy, weight loss, and a cane without adequate relief. Examination shows limited internal rotation and flexion of the right hip with pain. Radiographs show marked joint space loss, subchondral sclerosis, and large osteophytes of the right hip. Which of the following is the most appropriate next step in management?', '["Continue NSAIDs and add tramadol", "Intra-articular hyaluronic acid injection", "Hip arthroscopy to remove osteophytes", "Refer for total hip arthroplasty", "Start methotrexate"]'::jsonb, 3, 'This patient has severe, symptomatic hip osteoarthritis that has failed maximal conservative therapy, including NSAIDs, physical therapy, weight loss, and assistive devices, with radiographs showing advanced joint destruction. Total hip arthroplasty is the definitive treatment and is indicated when pain and functional limitation persist despite conservative measures. Continuing NSAIDs with tramadol does not address the destroyed joint and adds adverse effects. Hyaluronic acid injections have limited evidence in hip osteoarthritis. Hip arthroscopy is not indicated for advanced degenerative disease. Methotrexate is a disease-modifying drug for inflammatory arthritis and has no role in osteoarthritis, which is a degenerative, non-inflammatory process.', 'Medium', 92, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 64-year-old woman presents with 1 year of pain and stiffness in the distal interphalangeal joints of both hands. Examination shows hard, bony nodules at the distal interphalangeal joints (Heberden nodes) and proximal interphalangeal joints (Bouchard nodes) without warmth, erythema, or soft tissue swelling. Radiographs show osteophyte formation and joint space narrowing at the distal interphalangeal joints. Laboratory studies including ESR, CRP, and rheumatoid factor are normal. Which of the following is the most appropriate management?', '["Methotrexate weekly", "Oral prednisone", "Topical NSAIDs, hand exercises, and splinting", "Colchicine daily", "Distal interphalangeal joint fusion surgery"]'::jsonb, 2, 'Heberden and Bouchard nodes with normal inflammatory markers and radiographic osteophytes are characteristic of hand osteoarthritis, which predominantly affects the distal interphalangeal joints, unlike rheumatoid arthritis, which spares them. Management is conservative: topical NSAIDs, hand exercises, occupational therapy, and splinting for symptom control. Methotrexate and oral prednisone treat inflammatory arthritis and have no role in osteoarthritis. Colchicine is used for gout and pericarditis, not osteoarthritis. Joint fusion surgery is reserved for severe, refractory, painful deformity and is not first-line. Patient education and activity modification are important adjuncts.', 'Medium', 93, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 36-year-old woman presents with 6 months of widespread musculoskeletal pain affecting both sides of her body, above and below the waist. She reports profound fatigue, unrefreshing sleep, difficulty concentrating, and headaches. Examination shows multiple tender points without joint swelling, warmth, or muscle weakness. Laboratory studies show a normal complete blood count, ESR, CRP, creatine kinase, rheumatoid factor, and antinuclear antibody. Which of the following is the most appropriate next step in management?', '["Prednisone and reassurance that the pain is not real", "Methotrexate for presumed rheumatoid arthritis", "Diagnosis of fibromyalgia; graded aerobic exercise and duloxetine", "Tramadol around the clock", "Refer for joint replacement evaluation"]'::jsonb, 2, 'This patient meets criteria for fibromyalgia: widespread pain for more than 3 months with fatigue, sleep disturbance, and cognitive symptoms, and no other disease explaining the pain, with normal inflammatory markers and examination. Fibromyalgia is a disorder of central pain processing, not inflammation, so glucocorticoids and methotrexate are ineffective. First-line treatment is graded aerobic exercise, which improves pain and function, plus a serotonin-norepinephrine reuptake inhibitor such as duloxetine or a tricyclic such as amitriptyline for pain and sleep. Opioids are not recommended because they worsen outcomes and cause dependence. Reassurance alone without a treatment plan is inadequate.', 'Medium', 94, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 41-year-old woman with fibromyalgia diagnosed 2 years ago returns for follow-up. She has comorbid depression and poor sleep, and nonsteroidal anti-inflammatory drugs have not helped her pain. She exercises rarely because of fatigue. She asks what treatment is most likely to help both her pain and her mood. Which of the following is the most appropriate treatment plan?', '["High-dose prednisone", "Weekly methotrexate", "Daily oxycodone", "Intra-articular steroid injections", "Aerobic exercise, cognitive behavioral therapy, and duloxetine"]'::jsonb, 4, 'Fibromyalgia is a central sensitization disorder, and its most effective treatments target pain processing rather than inflammation. Aerobic exercise is first-line and improves pain, fatigue, and function. Cognitive behavioral therapy helps patients manage symptoms and improves coping. Duloxetine, a serotonin-norepinephrine reuptake inhibitor, treats both fibromyalgia pain and comorbid depression and improves sleep. Prednisone and methotrexate are ineffective because there is no peripheral inflammation. Opioids such as oxycodone are not recommended and worsen long-term outcomes. Intra-articular steroid injections have no role in a widespread, non-articular pain syndrome.', 'Medium', 95, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 58-year-old man presents to the emergency department with 1 day of acute pain, swelling, warmth, and redness of the right knee. He has a temperature of 38.9 C, cannot bear weight, and the knee is held in slight flexion. Laboratory studies show a white blood cell count of 14,000 per microliter and an ESR of 95 mm per hour. He has no history of gout or trauma. Which of the following is the most appropriate next step in management?', '["Nonsteroidal anti-inflammatory drugs and discharge home", "Oral cephalexin and follow-up in 1 week", "Magnetic resonance imaging of the knee before any intervention", "Emergent arthrocentesis with Gram stain and culture, empiric intravenous vancomycin, and orthopedic consultation", "Intra-articular corticosteroid injection"]'::jsonb, 3, 'An acutely hot, swollen, painful monoarticular joint with fever and leukocytosis is septic arthritis until proven otherwise, and it is a rheumatologic emergency because cartilage destruction occurs within days. Emergent arthrocentesis for cell count, Gram stain, culture, and crystal analysis is required, followed by empiric intravenous antibiotics covering Staphylococcus aureus, typically vancomycin, plus orthopedic consultation for drainage. NSAIDs and discharge risk joint destruction and sepsis. Oral antibiotics are inadequate for a closed-space joint infection. MRI should not delay aspiration. Intra-articular corticosteroids are contraindicated in suspected infection and would worsen it.', 'Hard', 96, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 24-year-old sexually active woman presents with 4 days of migratory joint pain involving her wrists, ankles, and knees, along with tenosynovitis of the right wrist and a few painless pustular skin lesions on her hands. She has a low-grade fever and no vaginal discharge. Examination shows tender, swollen joints without large effusions. Which of the following is the most likely diagnosis and appropriate treatment?', '["Reactive arthritis; nonsteroidal anti-inflammatory drugs alone", "Disseminated gonococcal infection; ceftriaxone plus sexually transmitted infection testing and partner treatment", "Methicillin-resistant Staphylococcus aureus septic arthritis; vancomycin", "Gout; colchicine", "Systemic lupus erythematosus; prednisone"]'::jsonb, 1, 'The triad of migratory polyarthralgia, tenosynovitis, and pustular dermatitis in a young sexually active patient is classic for disseminated gonococcal infection, which typically causes a non-purulent polyarticular arthritis rather than a single purulent joint. Treatment is ceftriaxone, along with testing for chlamydia and other sexually transmitted infections and treatment of sexual partners. Reactive arthritis follows a gastrointestinal or genitourinary infection but does not cause pustular lesions or tenosynovitis. Staphylococcal septic arthritis usually involves a single large joint with a large effusion. Gout causes monoarticular attacks with crystals, and lupus causes a different pattern of arthritis without pustules.', 'Medium', 97, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 63-year-old man presents with a painful, swollen right knee for 2 days. Arthrocentesis shows synovial fluid with a white blood cell count of 85,000 per microliter with 92 percent neutrophils. Gram stain shows no organisms and no crystals are seen. He is afebrile but has a white blood cell count of 13,000 per microliter. Which of the following is the most appropriate next step in management?', '["Reassure and start nonsteroidal anti-inflammatory drugs for gout", "Wait for culture results before starting treatment", "Start empiric intravenous antibiotics for septic arthritis", "Inject intra-articular corticosteroids", "Begin allopurinol"]'::jsonb, 2, 'Synovial fluid with more than 50,000 white blood cells per microliter and more than 75 percent neutrophils is highly suggestive of septic arthritis, even when the Gram stain is negative, because Gram stain sensitivity is only about 50 percent. Empiric intravenous antibiotics must be started immediately while cultures are pending, because delay causes irreversible cartilage destruction. NSAIDs for presumed gout are inappropriate given the very high cell count and neutrophil predominance. Waiting for cultures wastes critical time. Intra-articular corticosteroids are contraindicated in suspected joint infection. Allopurinol treats chronic gout and has no role in an acute infected joint.', 'Hard', 98, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 61-year-old man with type 2 diabetes mellitus for 15 years presents with a 3-week history of a plantar foot ulcer with surrounding erythema and purulent drainage. Probing the ulcer reaches bone. He has a temperature of 38.2 C, a white blood cell count of 12,500 per microliter, and an ESR of 90 mm per hour. Plain radiographs show no bony changes. Which of the following is the most appropriate next step in management?', '["Oral antibiotics alone for 1 week", "Amputation of the forefoot", "Plain radiograph to exclude osteomyelitis", "Superficial wound swab culture only", "Magnetic resonance imaging of the foot, bone biopsy with cultures, and intravenous antibiotics"]'::jsonb, 4, 'A positive probe-to-bone test in a diabetic foot ulcer is highly predictive of osteomyelitis, and this patient has supporting signs of infection including fever, leukocytosis, and a markedly elevated ESR. Magnetic resonance imaging is the most sensitive imaging test for osteomyelitis, and bone biopsy with culture is the gold standard for diagnosis and guiding antibiotics. Intravenous antibiotics are required for bone infection. Oral antibiotics alone are inadequate. Amputation is not first-line when the limb is salvageable. Plain radiographs are insensitive early in osteomyelitis. Superficial swab cultures reflect colonizing organisms and do not reliably identify the bone pathogen.', 'Hard', 99, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 47-year-old man with a history of intravenous drug use presents with 3 weeks of severe lower back pain, fever, and malaise. Examination shows tenderness over the L4 vertebra and paraspinal muscle spasm. Laboratory studies show a white blood cell count of 13,000 per microliter, an ESR of 110 mm per hour, and a CRP of 18 mg per dL. Neurologic examination is normal. Which of the following is the most appropriate next step in management?', '["Magnetic resonance imaging of the spine, blood cultures, and empiric intravenous antibiotics for vertebral osteomyelitis", "Nonsteroidal anti-inflammatory drugs and bed rest", "Oral antibiotics for 7 days", "Lumbar radiograph only", "Epidural steroid injection"]'::jsonb, 0, 'Vertebral osteomyelitis should be suspected in a patient with intravenous drug use, subacute back pain, fever, and markedly elevated inflammatory markers. Magnetic resonance imaging with gadolinium is the imaging test of choice, and blood cultures should be obtained before starting empiric intravenous antibiotics, which are typically directed against Staphylococcus aureus. NSAIDs and bed rest would miss a serious spinal infection that can progress to epidural abscess and neurologic injury. Oral antibiotics are inadequate for vertebral osteomyelitis, which requires prolonged intravenous therapy. Plain radiographs are insensitive early in the disease. Epidural steroid injection is contraindicated in suspected infection.', 'Hard', 100, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 54-year-old woman presents with a draining sinus tract over the anterior tibia that has persisted for 6 months after surgical fixation of a tibial fracture. She has intermittent low-grade fevers and dull aching pain in the leg. Radiographs show a sequestrum with surrounding involucrum and periosteal new bone formation. Which of the following is the most appropriate management?', '["Two weeks of oral antibiotics", "Surgical debridement plus 4 to 6 weeks of intravenous antibiotics", "Amputation is always required", "Topical antibiotics to the sinus tract", "Hyperbaric oxygen therapy alone"]'::jsonb, 1, 'This patient has chronic osteomyelitis, characterized by a draining sinus, sequestrum, and involucrum months after fracture fixation. Chronic osteomyelitis involves necrotic bone that antibiotics cannot penetrate, so surgical debridement of infected and dead bone is essential, followed by 4 to 6 weeks of intravenous antibiotics directed by bone cultures. Two weeks of oral antibiotics cannot sterilize necrotic bone. Amputation is reserved for unsalvageable limbs or life-threatening infection, not routine chronic osteomyelitis. Topical antibiotics do not reach bone. Hyperbaric oxygen is only an adjunct in selected cases and never replaces debridement and antibiotics.', 'Medium', 101, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 33-year-old woman presents with her second deep vein thrombosis in 2 years and a history of three first-trimester miscarriages. Laboratory studies show a prolonged activated partial thromboplastin time that does not correct with a mixing study. Anticardiolipin IgG antibodies are strongly positive and the lupus anticoagulant is present on repeat testing 12 weeks apart. Which of the following is the most likely diagnosis and appropriate long-term treatment?', '["Aspirin alone", "Apixaban indefinitely", "Heparin only during pregnancy", "Antiphospholipid syndrome; lifelong warfarin to an INR of 2 to 3", "Prednisone daily"]'::jsonb, 3, 'Antiphospholipid syndrome is diagnosed by a thrombotic event or pregnancy morbidity plus persistently positive antiphospholipid antibodies, including lupus anticoagulant or anticardiolipin antibodies, confirmed at least 12 weeks apart. The prolonged aPTT that fails to correct on mixing study reflects the lupus anticoagulant interfering with phospholipid-dependent clotting assays. Patients with thrombotic antiphospholipid syndrome require lifelong anticoagulation with warfarin to an INR of 2 to 3. Aspirin alone is insufficient after thrombosis. Direct oral anticoagulants are not recommended for thrombotic antiphospholipid syndrome because of higher recurrence rates. Prednisone does not prevent thrombosis.', 'Hard', 102, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 29-year-old woman with antiphospholipid syndrome and a prior fetal loss at 20 weeks of gestation presents at 8 weeks of pregnancy. She has no history of thrombosis. Her obstetrician asks about the most appropriate management to prevent another pregnancy loss. Which of the following is the most appropriate management during this pregnancy?', '["Low-molecular-weight heparin plus low-dose aspirin throughout pregnancy", "Warfarin throughout pregnancy", "Apixaban", "No anticoagulation; observation only", "Intravenous immunoglobulin alone"]'::jsonb, 0, 'In obstetric antiphospholipid syndrome, the combination of prophylactic low-molecular-weight heparin and low-dose aspirin throughout pregnancy and the postpartum period significantly improves live birth rates by preventing placental thrombosis and insufficiency. Warfarin is teratogenic and contraindicated in pregnancy, particularly in the first trimester. Direct oral anticoagulants such as apixaban are also contraindicated in pregnancy. Observation without treatment carries a high risk of recurrent fetal loss. Intravenous immunoglobulin is reserved for refractory cases and is not first-line. Low-dose aspirin alone is less effective than the combination regimen.', 'Medium', 103, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 38-year-old woman presents with 1 year of episodic color changes in her fingers triggered by cold, now with painful digital ulcers on two fingertips. Examination shows puffy fingers, sclerodactyly, and telangiectasias. Antinuclear antibody is positive at a titer of 1:640 with a centromere pattern. Which of the following is the most appropriate next step in management?', '["Reassurance only", "Start a beta-blocker", "Evaluate for systemic sclerosis and start a calcium channel blocker", "Digital sympathectomy now", "High-dose prednisone"]'::jsonb, 2, 'This patient has secondary Raynaud phenomenon due to systemic sclerosis, suggested by digital ulcers, sclerodactyly, telangiectasias, and a positive antinuclear antibody with a centromere pattern. She requires evaluation for systemic sclerosis, including nailfold capillaroscopy and screening for interstitial lung disease and pulmonary hypertension. Calcium channel blockers such as nifedipine are first-line for Raynaud phenomenon and reduce the frequency and severity of attacks. Reassurance alone is inadequate with digital ulcers. Beta-blockers worsen Raynaud phenomenon by causing vasoconstriction. Sympathectomy is reserved for refractory cases. High-dose prednisone does not treat Raynaud phenomenon.', 'Hard', 104, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 22-year-old healthy woman presents with 2 years of episodic color changes in her fingers when exposed to cold, progressing from white to blue to red, with mild tingling but no pain, ulcers, or tissue loss. Examination is normal between episodes, with no sclerodactyly, telangiectasias, or joint abnormalities. Antinuclear antibody is negative and inflammatory markers are normal. Which of the following is the most appropriate management?', '["Start nifedipine immediately", "Keep hands warm, avoid cold exposure and smoking, with no drug therapy needed", "Methotrexate", "Prednisone", "Refer for sympathectomy"]'::jsonb, 1, 'This patient has primary Raynaud phenomenon: episodic triphasic color changes triggered by cold in a young woman with a normal examination, negative autoantibodies, and no features of connective tissue disease. Primary Raynaud phenomenon is managed conservatively with keeping the hands warm, avoiding cold exposure, smoking cessation, and avoiding vasoconstrictive medications such as beta-blockers and decongestants. Drug therapy with calcium channel blockers is reserved for frequent, severe, or ulcerating attacks. Methotrexate and prednisone treat inflammatory disease and have no role here. Sympathectomy is reserved for severe refractory secondary Raynaud phenomenon with tissue loss.', 'Easy', 105, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 27-year-old man presents with 6 months of low back pain that is worse in the morning and at night and improves with exercise and movement. He reports 2 hours of morning stiffness and pain that does not improve with rest. Nonsteroidal anti-inflammatory drugs provide significant relief. Examination shows limited lumbar flexion and tenderness over the sacroiliac joints. Which of the following is the most likely diagnosis and initial management?', '["Bed rest and opioids", "Lumbar fusion surgery", "Oral corticosteroids", "Methotrexate", "Ankylosing spondylitis; nonsteroidal anti-inflammatory drugs, exercise, and sacroiliac joint imaging"]'::jsonb, 4, 'Inflammatory back pain is characterized by onset before age 40, insidious onset, improvement with exercise but not rest, nocturnal pain, and prolonged morning stiffness, all present in this patient. Ankylosing spondylitis is the most likely diagnosis and is associated with HLA-B27 and sacroiliitis. First-line treatment is nonsteroidal anti-inflammatory drugs combined with regular exercise and physical therapy to maintain spinal mobility. Bed rest and opioids worsen stiffness and function. Lumbar fusion is not a treatment for inflammatory spinal disease. Oral corticosteroids are ineffective for axial disease. Methotrexate helps peripheral arthritis but not axial ankylosing spondylitis.', 'Medium', 106, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 45-year-old man presents with 2 days of acute low back pain, numbness in the perineal area, difficulty urinating with urinary retention, and weakness in both legs. He also reports decreased sensation in the saddle distribution. Examination shows reduced anal sphincter tone and bilateral lower extremity weakness. Which of the following is the most appropriate next step in management?', '["Emergent magnetic resonance imaging and neurosurgical consultation for cauda equina syndrome", "Nonsteroidal anti-inflammatory drugs and physical therapy", "Reassurance and follow-up in 6 weeks", "Epidural steroid injection", "Plain lumbar radiographs only"]'::jsonb, 0, 'Saddle anesthesia, urinary retention, and bilateral leg weakness in the setting of acute back pain are classic for cauda equina syndrome, a neurosurgical emergency caused by compression of the lumbosacral nerve roots. Emergent magnetic resonance imaging is required to confirm the diagnosis, followed by urgent surgical decompression, ideally within 24 hours, to preserve bladder, bowel, and motor function. Conservative management with NSAIDs and physical therapy would cause irreversible neurologic damage. Reassurance and delayed follow-up are dangerous. Epidural steroid injection is contraindicated with a compressive lesion and neurologic deficit. Plain radiographs cannot evaluate the nerve roots or spinal canal.', 'Hard', 107, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 30-year-old man presents with 3 years of chronic low back pain and morning stiffness lasting more than 1 hour. The pain improves with movement and exercise but worsens with rest and inactivity. He reports alternating buttock pain. Testing shows HLA-B27 positivity, and radiographs show bilateral sacroiliitis. Which of the following is the most likely diagnosis?', '["Lumbar disc herniation", "Spinal osteoarthritis", "Fibromyalgia", "Ankylosing spondylitis", "Vertebral compression fracture"]'::jsonb, 3, 'This patient has ankylosing spondylitis, a seronegative spondyloarthropathy characterized by inflammatory back pain, alternating buttock pain from sacroiliitis, prolonged morning stiffness that improves with exercise, and association with HLA-B27. Radiographic sacroiliitis confirms the diagnosis. Lumbar disc herniation causes radicular pain worsened by activity and Valsalva, not morning stiffness that improves with movement. Spinal osteoarthritis affects older adults and worsens with activity. Fibromyalgia causes widespread pain without inflammatory features or radiographic changes. Vertebral compression fracture causes acute, localized pain after minor trauma, typically in osteoporotic patients.', 'Medium', 108, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 57-year-old man presents with 4 months of right shoulder pain that worsens with overhead activity and at night. He has no history of trauma. Examination shows pain on abduction between 60 and 120 degrees, tenderness over the greater tuberosity, and mild weakness on resisted abduction. Passive range of motion is full. Which of the following is the most appropriate initial management?', '["Immediate rotator cuff repair surgery", "Nonsteroidal anti-inflammatory drugs and physical therapy for rotator cuff tendinopathy", "Intra-articular corticosteroid injection as first-line therapy", "Total shoulder arthroplasty", "Antibiotics for septic arthritis"]'::jsonb, 1, 'This patient has rotator cuff tendinopathy, suggested by insidious onset, pain with overhead activity, a painful arc between 60 and 120 degrees of abduction, and night pain without trauma. First-line management is conservative: nonsteroidal anti-inflammatory drugs for pain and a structured physical therapy program to strengthen the rotator cuff and scapular stabilizers. Most patients improve without surgery. Immediate surgical repair is reserved for acute traumatic tears or failure of conservative therapy. Intra-articular corticosteroid injection is not first-line and provides only short-term relief. Total shoulder arthroplasty is for advanced glenohumeral arthritis, not tendinopathy. Antibiotics are not indicated without signs of infection.', 'Medium', 109, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 66-year-old woman presents with 6 months of progressive right shoulder weakness and pain. She cannot lift her arm overhead and reports difficulty combing her hair. Examination shows atrophy of the supraspinatus muscle, a positive drop-arm test, and weakness on resisted external rotation. Passive range of motion is preserved. Which of the following is the most appropriate next step in management?', '["Physical therapy alone for 6 months", "Nonsteroidal anti-inflammatory drugs only", "Magnetic resonance imaging of the shoulder and orthopedic referral for full-thickness rotator cuff tear", "Reassurance", "Repeated corticosteroid injections"]'::jsonb, 2, 'Inability to actively elevate the arm, a positive drop-arm test, and supraspinatus atrophy suggest a full-thickness rotator cuff tear. Magnetic resonance imaging is the best test to confirm the diagnosis, define the size and retraction of the tear, and assess muscle atrophy and fatty infiltration, which guide surgical planning. Orthopedic referral is appropriate because surgical repair is often indicated for symptomatic full-thickness tears, particularly in active patients. Physical therapy alone is insufficient for a complete tear with atrophy. NSAIDs alone do not restore function. Reassurance ignores a surgically correctable lesion. Repeated corticosteroid injections provide only temporary relief and can weaken the tendon further.', 'Hard', 110, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 34-year-old woman at 32 weeks of pregnancy presents with 3 weeks of nocturnal numbness and tingling in the thumb, index, and middle fingers of her right hand. She shakes her hand to relieve the symptoms. Examination shows a positive Tinel sign over the wrist and a positive Phalen test. There is no thenar atrophy or weakness. Which of the following is the most appropriate initial management?', '["Night wrist splint in neutral position and activity modification", "Immediate carpal tunnel release surgery", "Oral prednisone", "Methotrexate", "Gabapentin as first-line therapy"]'::jsonb, 0, 'This patient has carpal tunnel syndrome, the most common entrapment neuropathy, caused by compression of the median nerve at the wrist. Pregnancy is a common precipitant because of fluid retention and edema. Classic features include nocturnal paresthesias in the thumb, index, and middle fingers, with positive Tinel and Phalen signs. First-line management is conservative: a neutral wrist splint worn at night, activity modification, and avoidance of repetitive wrist flexion. Symptoms often resolve after delivery. Surgery is reserved for severe or persistent cases. Oral prednisone and methotrexate have no role. Gabapentin is not first-line for entrapment neuropathy.', 'Medium', 111, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 52-year-old man presents with 1 year of progressive numbness and tingling in the thumb, index, and middle fingers of his dominant hand. The numbness is now constant, and he has noticed wasting of the thenar eminence and difficulty buttoning his shirt. Night splinting has not helped. Examination shows thenar atrophy and decreased two-point discrimination in the median nerve distribution. Which of the following is the most appropriate next step in management?', '["Continue splinting indefinitely", "Nonsteroidal anti-inflammatory drugs alone", "Physical therapy only", "Nerve conduction studies and referral for carpal tunnel release", "Reassurance"]'::jsonb, 3, 'Thenar atrophy and constant numbness indicate severe, chronic median nerve compression with axonal loss, which is unlikely to improve with splinting alone. Nerve conduction studies and electromyography confirm the diagnosis, grade severity, and exclude other causes such as cervical radiculopathy or polyneuropathy. Surgical referral for carpal tunnel release is indicated for severe disease with thenar atrophy or persistent symptoms despite conservative measures. Continuing splinting indefinitely risks permanent nerve damage. NSAIDs alone do not relieve mechanical compression. Physical therapy does not decompress the nerve. Reassurance ignores progressive, irreversible median nerve injury.', 'Hard', 112, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 48-year-old woman presents with 4 months of progressive proximal muscle weakness, difficulty swallowing, and shortness of breath on exertion. Examination shows symmetric proximal weakness, roughened hyperkeratotic skin on the fingers known as mechanic''s hands, and bibasilar crackles. Laboratory studies show a creatine kinase of 4,500 U per L. Anti-Jo-1 antibodies are positive. Chest imaging shows bibasilar interstitial infiltrates. Which of the following is the most likely diagnosis and appropriate management?', '["Reassurance and exercise", "Nonsteroidal anti-inflammatory drugs alone", "Methotrexate alone", "Intravenous immunoglobulin only", "Antisynthetase syndrome with polymyositis and interstitial lung disease; high-dose glucocorticoids and interstitial lung disease evaluation"]'::jsonb, 4, 'This patient has antisynthetase syndrome, an inflammatory myopathy associated with anti-Jo-1 antibodies, characterized by polymyositis, interstitial lung disease, mechanic''s hands, Raynaud phenomenon, and arthritis. High-dose glucocorticoids are the mainstay of treatment for inflammatory myopathy, and evaluation and treatment of interstitial lung disease are critical because it determines prognosis. Reassurance and exercise alone are inadequate for active myositis with dysphagia and lung involvement. NSAIDs do not treat inflammatory myopathy. Methotrexate alone is too slow and may worsen interstitial lung disease. Intravenous immunoglobulin is an adjunct for refractory disease, not sole first-line therapy.', 'Hard', 113, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 29-year-old woman presents with Raynaud phenomenon, swollen hands, proximal muscle weakness, difficulty swallowing, and joint pain. Laboratory studies show a high-titer anti-U1 ribonucleoprotein antibody, positive antinuclear antibody, and elevated creatine kinase. She has features suggestive of lupus, scleroderma, and polymyositis simultaneously. Which of the following is the most likely diagnosis?', '["Mixed connective tissue disease", "Systemic lupus erythematosus", "Rheumatoid arthritis", "Diffuse systemic sclerosis", "Sjogren syndrome"]'::jsonb, 0, 'Mixed connective tissue disease is an overlap syndrome characterized by features of systemic lupus erythematosus, systemic sclerosis, and polymyositis, in association with high-titer anti-U1 ribonucleoprotein antibodies. The combination of Raynaud phenomenon, swollen hands, myositis, esophageal dysmotility, and anti-U1 RNP is characteristic. Systemic lupus erythematosus alone does not typically cause sclerodactyly or prominent myositis. Rheumatoid arthritis causes symmetric inflammatory polyarthritis with erosions but not this overlap pattern. Diffuse systemic sclerosis does not explain the lupus-like features or myositis. Sjogren syndrome causes sicca symptoms and is associated with anti-SSA and anti-SSB antibodies.', 'Medium', 114, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 58-year-old man presents with sudden onset of severe pain, redness, and swelling of the right great toe that began overnight. Examination shows a hot, erythematous, exquisitely tender first metatarsophalangeal joint. Arthrocentesis shows synovial fluid with a white blood cell count of 18,000 per microliter and needle-shaped negatively birefringent crystals on polarized light microscopy. Which of the following is the most likely diagnosis and appropriate initial treatment?', '["Septic arthritis; intravenous antibiotics", "Gout; nonsteroidal anti-inflammatory drugs or colchicine", "Pseudogout; nonsteroidal anti-inflammatory drugs", "Osteoarthritis; acetaminophen", "Rheumatoid arthritis; methotrexate"]'::jsonb, 1, 'Acute podagra with a hot, red, swollen first metatarsophalangeal joint and needle-shaped negatively birefringent crystals on polarized microscopy is diagnostic of gout. The synovial fluid white blood cell count is in the inflammatory range but well below the typical septic range, and crystals confirm the diagnosis. Acute gout is treated with nonsteroidal anti-inflammatory drugs, colchicine, or glucocorticoids. Septic arthritis would show a much higher white blood cell count, usually above 50,000, and no crystals. Pseudogout crystals are rhomboid and positively birefringent. Osteoarthritis fluid is non-inflammatory. Rheumatoid arthritis causes chronic symmetric polyarthritis, not an acute monoarticular attack with crystals.', 'Medium', 115, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 72-year-old woman presents with 2 days of acute left knee swelling and pain without fever or trauma. Arthrocentesis shows synovial fluid with a white blood cell count of 12,000 per microliter and rhomboid-shaped positively birefringent crystals. Radiographs show calcification of the meniscal cartilage consistent with chondrocalcinosis. Which of the following is the most likely diagnosis?', '["Gout", "Septic arthritis", "Calcium pyrophosphate deposition disease (pseudogout)", "Rheumatoid arthritis", "Osteoarthritis"]'::jsonb, 2, 'Calcium pyrophosphate deposition disease, or pseudogout, typically affects older adults and presents with acute monoarthritis, most commonly of the knee. Synovial fluid shows weakly positively birefringent rhomboid-shaped crystals, and radiographs often show chondrocalcinosis. Gout crystals are needle-shaped and negatively birefringent. Septic arthritis would have a much higher synovial white blood cell count, usually above 50,000 per microliter, with a predominance of neutrophils. Rheumatoid arthritis causes chronic symmetric small-joint polyarthritis with a high synovial white blood cell count but no crystals. Osteoarthritis synovial fluid is non-inflammatory with fewer than 2,000 white blood cells.', 'Medium', 116, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 45-year-old woman presents with 3 months of symmetric swelling and pain of the metacarpophalangeal and proximal interphalangeal joints of both hands, with morning stiffness lasting more than 1 hour. Rheumatoid factor is positive. Her physician wants to order the most specific laboratory test to confirm the diagnosis of rheumatoid arthritis. Which of the following tests is most specific for rheumatoid arthritis?', '["Antinuclear antibody", "Erythrocyte sedimentation rate", "Rheumatoid factor", "Anti-cyclic citrullinated peptide antibody", "HLA-B27"]'::jsonb, 3, 'Anti-cyclic citrullinated peptide antibody is the most specific serologic test for rheumatoid arthritis, with specificity greater than 95 percent, and it can be positive early in disease, even before rheumatoid factor. Rheumatoid factor is sensitive but less specific and can be positive in other conditions such as chronic infections, Sjogren syndrome, and healthy older adults. Antinuclear antibody is a screening test for systemic lupus erythematosus and other connective tissue diseases. ESR is a nonspecific marker of inflammation. HLA-B27 is associated with seronegative spondyloarthropathies such as ankylosing spondylitis, not rheumatoid arthritis.', 'Medium', 117, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 26-year-old woman presents with a malar rash, photosensitivity, oral ulcers, proteinuria, leukopenia, and thrombocytopenia. Antinuclear antibody is positive at a titer of 1:1280 with a homogeneous pattern. Which of the following antibodies is most specific for systemic lupus erythematosus?', '["Anti-double-stranded DNA", "Anti-Scl-70", "Anti-Jo-1", "Anti-centromere", "Anti-SSA/Ro"]'::jsonb, 0, 'Anti-double-stranded DNA antibody is highly specific for systemic lupus erythematosus and correlates with disease activity, particularly lupus nephritis. This patient has classic lupus features including malar rash, photosensitivity, oral ulcers, proteinuria, and cytopenias. Anti-Scl-70 is associated with diffuse systemic sclerosis. Anti-Jo-1 is associated with polymyositis and antisynthetase syndrome. Anti-centromere is associated with limited systemic sclerosis, or CREST syndrome. Anti-SSA, or anti-Ro, is associated with Sjogren syndrome and neonatal lupus but is less specific for systemic lupus erythematosus than anti-double-stranded DNA.', 'Medium', 118, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 74-year-old woman presents with 2 months of bilateral shoulder and hip girdle pain and stiffness, morning stiffness lasting 2 hours, and low-grade fever. She has difficulty raising her arms above her head and rising from a chair. Laboratory studies show an ESR of 95 mm per hour, an elevated CRP, and a normal creatine kinase. Muscle strength testing is normal. Which of the following is the most likely diagnosis and appropriate treatment?', '["Fibromyalgia; exercise only", "Polymyositis; high-dose steroids", "Rheumatoid arthritis; methotrexate", "Osteoarthritis; nonsteroidal anti-inflammatory drugs", "Polymyalgia rheumatica; low-dose prednisone with dramatic response"]'::jsonb, 4, 'Polymyalgia rheumatica affects adults over age 50 and presents with bilateral shoulder and hip girdle pain and stiffness, morning stiffness, low-grade fever, and markedly elevated ESR and CRP, with a normal creatine kinase and no true muscle weakness. The key distinguishing feature is a dramatic response to low-dose prednisone, usually 15 to 20 mg daily, with improvement within days. Fibromyalgia causes widespread pain with normal inflammatory markers. Polymyositis causes true weakness with elevated creatine kinase. Rheumatoid arthritis causes small-joint synovitis, not isolated girdle pain. Osteoarthritis does not cause markedly elevated ESR or systemic symptoms.', 'Medium', 119, 'MCQ'),
('e02346b8-4f3d-462d-90a2-eb207dfd0474', 'A 68-year-old man presents with chronic bilateral knee pain that worsens with activity. Arthrocentesis of the right knee yields clear, straw-colored fluid with a white blood cell count of 800 per microliter with 20 percent neutrophils and no crystals on polarized microscopy. Which of the following is the most likely diagnosis?', '["Septic arthritis", "Gout", "Rheumatoid arthritis", "Pseudogout", "Osteoarthritis (non-inflammatory fluid)"]'::jsonb, 4, 'Osteoarthritis produces non-inflammatory synovial fluid: clear, straw-colored, with fewer than 2,000 white blood cells per microliter and a low neutrophil percentage, without crystals. In contrast, septic arthritis shows more than 50,000 white blood cells with neutrophil predominance, gout shows needle-shaped negatively birefringent crystals, pseudogout shows rhomboid positively birefringent crystals, and rheumatoid arthritis shows inflammatory fluid with 2,000 to 75,000 white blood cells but no crystals. This patient''s fluid is classic for degenerative joint disease. Management focuses on weight loss, exercise, topical and oral nonsteroidal anti-inflammatory drugs, and eventually joint replacement if symptoms become refractory.', 'Easy', 120, 'MCQ');
